window.tanimlarData = [
  {"t":"Acrabadin","c":"Hastalıkların ilâclarını bildiren kitâblara, (Kitâb-ül-edviye), (formüler farmasötik) ve (Acrabadin) denir.","s":652},
  {"t":"Adâlet","c":"Adâletin yüksek ta’rîfi, (Kendi mülkünde olanı kullanmak) demekdir.","s":403},
  {"t":"Âdetde bid’at","c":"Böyle, Allahü teâlâya ibâdet etmek ve sevâb kazanmak niyyeti olmaksızın meydâna çıkarılan şeylere, (Âdetde bid’at) denir.","s":631},
  {"t":"Âdet zemânı","c":"Hayz kanı görüldüğü andan, kesildiği güne kadar olan günlerin sayısına (Âdet zemânı) denir.","s":136},
  {"t":"Âdil","c":"Büyük günâh işlemiyen ve küçük günâha devâm etmeyen ve hasenesi seyyiesinden çok olan müslimâna (Âdil) denir.","s":884},
  {"t":"Âhıret hayâtı","c":"Kıyâmetden önceki zemân, kıyâmetden sonraki zemândan dahâ yakın olduğu için, birincisine (Dünyâ hayâtı), ikincisine (Âhıret hayâtı) denir.","s":78},
  {"t":"Ahkâm-ı islâmiyye","c":"Bu emr ve yasakların hepsine (Ahkâm-ı ilâhiyye) veyâ (Ef’âl-i mükellefîn) ve (Ahkâm-ı islâmiyye) denir. (Ef’âl-i mükellefîn) sekizdir. Farz, vâcib, sünnet, müstehab, mubâh, harâm, mekrûh, müfsid.","s":18},
  {"t":"Akl","c":"Allahü teâlâ, çok merhametli olduğu için, insanda, iyi işleri kötülerinden ayıran bir kuvvet yaratdı. Bu kuvvete (Akl) denir.","s":1248},
  {"t":"Akl-ı selîm","c":"Şaşmıyan, yanılmıyan akla (Akl-ı selîm) denir.","s":530},
  {"t":"Akrabâ","c":"Analardan, baba ve dedelerden ve çocuklardan, torunlardan başka olan yakınlara, (Akrabâ) denir.","s":595},
  {"t":"Aks-i sadâ","c":"Geri dönen dalgalar, eşit özellikde, ikinci bir ses meydâna getirirler. Bu ikinci sese (Aks-i sadâ) veyâ (yankı) denir.","s":725},
  {"t":"Alâmet","c":"Her şeyin vücûdü, ya’nî var olması, bir işin yapılmasına bağlıdır. Bu bağlılık, beş dürlü olur: İş, bu şeyin mâhiyyetinin içinde ise, onun bir parçası ise, bu işe, (Rükn) denir. Dışında ise, bu şeye te’sîr ediyorsa, (İllet) denir. Nikâh, evlenmenin illetidir. Te’sîr etmiyorsa, işin yapılması, bu şeyin vücûdünü îcâb ediyorsa, (Sebeb) denir. Vakt, nemâzın sebebidir. Îcâb etmiyorsa, işin yapılmaması ile, o şey de yok olursa, (Şart) denir. Yok olmazsa, (Alâmet) denir.","s":122},
  {"t":"Âlem","c":"(Nebrâs) ve bunun Berhurdâr “rahmetullahi teâlâ aleyh” hâşiyesinde diyor ki: Mahlûkların hepsine (Âlem) denir.","s":758},
  {"t":"Âlem-i sagîr","c":"İnsana, (Âlem-i sagîr) denir.","s":86},
  {"t":"Alev","c":"Gazların, buhârların yanmasına (Alev) denir.","s":548},
  {"t":"Âmîn","c":"(Âmîn), (Kabûl et) demekdir.","s":215},
  {"t":"Anyon","c":"Eksi elektrik taşıyan atomlara (Anyon) denir.","s":547},
  {"t":"Arab-ı âribe","c":"Nûh aleyhisselâmdan sonra Arabistân yarım adasında yerleşenlere (Arab-ı bâide) denir. Âd, Semûd ve Amâlika bunlardandır. Hûd aleyhisselâm Âd kavmine, Sâlih aleyhisselâm Semûd kavmine gelmişlerdir. Hepsi (Sâm) soyundandır. Bunlardan sonra, gelip Yemene yerleşen (Kahtân) evlâdlarına (Arab-ı âribe) denir.","s":1128},
  {"t":"Arab-ı bâide","c":"Nûh aleyhisselâmdan sonra Arabistân yarım adasında yerleşenlere (Arab-ı bâide) denir.","s":1128},
  {"t":"Ârif","c":"Allahü teâlâya yakın olmak, Onun sevmesine kavuşmak demekdir. Bu se’âdete kavuşana (Velî) ve (Ârif) denir.","s":1057},
  {"t":"Arşullah","c":"Kâmil bir insanın kalbi, birçok bakımdan Arş gibidir. Bunun için, öyle kalbe (Arşullah) denir.","s":917},
  {"t":"Artık (su)","c":"Bir kabdan veyâ küçük havuzdan, bir canlı içerse, kalan suya (artık) denir.","s":162},
  {"t":"Artifisiel","c":"Birşeyin yaratılmasına sebeb olan şeyler arasında insan gücü de varsa, yaratılan şeye (Sun’î cism) veyâ (Artifisiel) denir.","s":433},
  {"t":"Ashâr","c":"Zevcesinden, zevcinden, zî-rahm-i mahrem kadın akrabâsının kocalarından ve zevcesinin zî-rahm-i mahrem erkek akrabâsından çalarsa kesilmez. Bu sonunculara (Ashâr) denir.","s":882},
  {"t":"Âşir","c":"(Âmil): Ya’nî Sâime hayvanların ve toprak mahsûllerinin zekâtlarını toplayan (Sâ’î) ile, şehr dışında durup rastladığı tüccârdan ticâret malı zekâtını toplıyan (Âşir), zengin dahî olsalar, işleri karşılığı zekât verilir.","s":307},
  {"t":"Atf-ı beyân","c":"Bir kimsenin iki ismi olup, bu iki ism, birlikde söylendiği vakt, birinin meşhûr olmadığı, ikincisinin meşhûr olduğu anlaşılır. Meşhûr olmıyan birincisindeki kapalılığı açıklamak için, ikincisi zikr edilir. Bu ikincisine, (Atf-ı beyân) denir.","s":389},
  {"t":"Atmosfer","c":"Hava, deniz kenârında, bir santimetre kare satha, bir kilogram tazyîk yapmakdadır. Bu basınc mikdârına, bir (Atmosfer) denir ki, yetmişaltı santimetre [76 cm] yüksekliğindeki cıvanın basıncına eşitdir.","s":980},
  {"t":"Atom","c":"Kimyâ reaksiyonlarında, maddelerin birbiri ile birleşen veyâ ayrılan en küçük parçasına (Atom) denir.","s":971},
  {"t":"Atom numarası","c":"Elementlerin devrî sistemdeki soldan sağa doğru sıra numarasına, (Atom numarası) denir.","s":549},
  {"t":"Avret mahalli","c":"Mükellef olan, ya’nî âkıl ve bâlig olan insanın nemâz kılarken açması veyâ her zemân başkasına göstermesi ve başkasının bakması harâm olan yerlerine (Avret mahalli) denir.","s":163},
  {"t":"Ayn","c":"Mal, (Ayn) ve (Deyn) olarak ikiye ayrılır: Ayn, lügatda madde, cism demekdir. Fekat, bey’ ve şirâ ilminde ayn, belli bir mal demekdir. Bey’ ve şirâda, bir ev, bir at, bir sandalye gibi kıyemî malların belli birer dânesine ve hâzır olup da gösterilenin hepsine veyâ ayrılmış parçasına, mislî olan mallardan da, hâzır olup gösterilen hepsine veyâ ayrı olarak gösterilen yâhud ayrılmamış belli mikdâr bir parçasına yâhud hâzır olmayıp, benzerlerinden ayrı ve yalnız olarak bulunduğu yeri ve cinsi bildirilen mala, (Ayn) denir.","s":793},
  {"t":"Ayn-ül-yakîn","c":"Hadîs-i şerîfde bildirilen (İhsân) mertebesinden bir ışıkın kalbde parlamasına, (Ayn-ül-yakîn) denir.","s":765},
  {"t":"Azâb","c":"Allahü teâlâ insanların yapdığı işlerden bir kısmını beğenmediğini, bunları yapanlardan râzı olmadığını, fekat pişmân olup tevbe edenleri veyâ şefâ’ate kavuşanları afv edeceğini, afv edilmiyenlerin kötü işlerine kıyâmetde, çok acı karşılıklar vereceğini, Cehennem ateşinde yakacağını bildirdi. Bu acı karşılıklara, (Azâb) denir.","s":681},
  {"t":"A’zamallahü ecrek ve ahsene azâek ve gafere limeyyitik","c":"Ta’ziye için, (A’zamallahü ecrek ve ahsene azâek ve gafere limeyyitik) denir ki, (Allahü teâlâ, sevâbını, dereceni artdırsın ve güzel sabr etmeni nasîb eylesin ve meyyitinin günâhlarını afv eylesin) demekdir.","s":1006},
  {"t":"Bâbürrahme","c":"Mescid-i Nebînin beş kapısı var idi. Bunlardan: İkisi garb dıvarında olup, kıbleye yakın olana, (Bâbüsselâm), şimâl köşesine yakın olana, (Bâbürrahme) denir.","s":348},
  {"t":"Bâbüt-tevessül","c":"Bedr gazâsından iki ay evvel, ya’nî ikinci senenin Receb ayında, Kıblenin Kâ’be cihetine tahvîli emr olununca, kapısı cenûb dıvarından şimâl dıvarına alınırken, mescidin tûlü ve arzı yüzer zrâ’ [42 metre] yapıldı. Bu kapıya (Bâbüt-tevessül) denir.","s":348},
  {"t":"Basît cism","c":"Element: Kendisinden, başka başka özellikde maddeler çıkarılamıyan saf maddelere (Element=eleman) veyâ (Basît cism) denir.","s":546},
  {"t":"Basît cism, eleman","c":"Bir sâf cismden, başka bir madde çıkarılamaz ise, bu maddeye (Basît cism, eleman) denir.","s":971},
  {"t":"Batı Avrupa zemânı","c":"Londra şehrinin yedibuçuk derece şarkından ve garbından geçen iki tûl dâiresi arasında bulunan her yerde Londranın vasatî sâati müşterek olarak kullanılmakdadır. Buna (Batı Avrupa zemânı) denir.","s":190},
  {"t":"Bat satışı","c":"Vefâ ile, ikrâh ile ve muhayyerlikle olmıyan şartsız satışlara, (Bat satışı) denir.","s":814},
  {"t":"Bedîhî","c":"Akl ile bilmek de ikidir: Düşünmeden hemen bilinirse, (Bedîhî) denir.","s":782},
  {"t":"Behâr hattı","c":"Husûf ve Ekvator düzlemleri Erdın bir kutru [çapı] üzerinde kesişirler. Aralarında takrîben 23,5 derece zâviye vardır. Erdın bu kutruna (Behâr hattı) denir.","s":183},
  {"t":"Benî-Hâşim","c":"Resûlullahın ve amcalarının oğullarına (Hâşimî) veyâ (Benî-Hâşim) denir.","s":1108},
  {"t":"Benûl-ahyâf","c":"Anadan kardeşler: Bunlara, (Benûl-ahyâf) denir.","s":1026},
  {"t":"Besmele","c":"Besmele okumak, (Bismillâhirrahmânirrahîm) demekdir.","s":3},
  {"t":"Bî’at-ür-rıdvân","c":"Muhyissünne imâm-ı Begavî “rahmetullahi teâlâ aleyh”, (Me’âlimüttenzîl) ismindeki tefsîr kitâbında, ma’nâ verirken diyor ki: Câbir bin Abdüllah “radıyallahü anh” dedi ki, Resûlullah “sallallahü aleyhi ve sellem”, (Ağaç altında benimle sözleşenlerden hiçbiri Cehenneme girmez!) buyurdu. Bu sözleşmeye, (Bî’at-ür-rıdvân) denir.","s":507},
  {"t":"Bid’at ehli","c":"Peygamberimiz, (İbâdetleri benden ve eshâbımdan gördüğünüz gibi yapınız! İbâdetlerde değişiklik yapanlara (bid’at ehli) denir. Bid’at sâhibleri, muhakkak Cehenneme gidecekdir. Bunların hiçbir ibâdetleri kabûl olmaz) buyurdu.","s":169},
  {"t":"Bid’at sâhibi","c":"Kur’ândan ve hadîsden yanlış ma’nâ çıkarana (Bid’at sâhibi) denir.","s":16},
  {"t":"Bid’at talâk","c":"Bir def’ada üç kerre talâk vermeğe, (Bid’at talâk) denir.","s":582},
  {"t":"Bileşik cism","c":"Başka maddelere ayrılabilen sâf cisme (Bileşik cism) denir.","s":971},
  {"t":"büyük havuz","c":"Eni on zrâ’ [4,8 metre], boyu da on zrâ’ olan kare şeklindeki havuza (büyük havuz) denir ki, sathı [alanı] yüz zrâ’ kare, ya’nî yirmiüç metre karedir.","s":161},
  {"t":"Câmi’","c":"Müslimânların ma’bedine (Mescid) ve (Câmi’) denir.","s":244},
  {"t":"Cennet","c":"Ni’metlerin verileceği yere, (Cennet) denir.","s":681},
  {"t":"Cin","c":"Cin, cinnet, cinân, Cennet, cenân ve cenîn gibi C ve N harflerinden meydâna gelen kelimeler (örtülü) demekdir.","s":735},
  {"t":"Cism","c":"Maddelerin şekl almış parçalarına, (Cism) denir.","s":971},
  {"t":"Contüsion","c":"Çok acır, sızlar. Buna (Ezik) veyâ (Contüsion) denir.","s":675},
  {"t":"Cünn-i leyl","c":"Geceye (Cünn-i leyl) denir.","s":735},
  {"t":"Cünüb","c":"Gusl abdesti olmıyana (Cünüb) denir.","s":122},
  {"t":"Çıkık","c":"(Nüzhet-ül-ebdân)da diyor ki, insan düşünce veyâ bir yere çarpınca, iğri basınca, oynak kemiği yerinden çıkar. Buna, (çıkık) denir.","s":675},
  {"t":"Dahk","c":"Nemâzda tebessüm, nemâzı da, abdesti de bozmaz. Yanındakiler işitirse, kahkaha denir. Kendi de işitmezse, tebessüm denir. Yalnız kendi işitirse (Dahk) denir.","s":127},
  {"t":"Dâlle","c":"Âdet zemânını unutan kadına (Muhayyire) veyâ (Dâlle) denir.","s":139},
  {"t":"Da’vâ açmak","c":"İhbar üç dürlü olur: a) Yukarıda bildirdiğimiz şâhidlikdir. b) Kendinin başkasında bulunan hakkını haber vermekdir. Buna (Da’vâ açmak) denir.","s":884},
  {"t":"Dehrî","c":"Hiçbir dîne inanmayanlara (Ateist) ve (Dehrî) denir.","s":1043},
  {"t":"Devrî tasnîf","c":"Yüzbeş elementin, yedi devr ve sekiz gurup teşkîl etmek üzere sıralanmasına, (Periyodik sistem) veyâ (Devrî tasnîf) denir.","s":549},
  {"t":"Deyn","c":"(Deyn): Satış ve ödünc verme veyâ başka sebeblerle ödenmesi lâzım olan borcdur. Alış verişde ise, hâzır olmayıp ayrı olarak bulunduğu yeri bildirilmiyen her dürlü mala ve hâzır ise de, ayrı olarak gösterilmiyen kıyemî mal parçasına, (Deyn) denir.","s":793},
  {"t":"Dinde reformcu","c":"Din bilgilerini, fen bilgilerine göre değişdiren kâfirlere (Felesof) ve (Dinde reformcu) denir.","s":1043},
  {"t":"Dîn-i islâm","c":"Ona tâbi’ olmak, ya’nî Ona uymak, Onun gitdiği yolda yürümekdir. Onun yolu, Kur’ân-ı kerîmin gösterdiği yoldur. Bu yola (Dîn-i islâm) denir.","s":17},
  {"t":"Dirhem","c":"Altın paralara (Dînâr), gümüş paralara (Dirhem) denir.","s":802},
  {"t":"Diyânât","c":"Allah ile kul arasında olan işlere (Diyânât) denir.","s":159},
  {"t":"Dünyâ","c":"Dünyâ, ednâ kelimesinin müennesidir. Ya’nî, ism-i tafdîldir. Masdarı, dünüv veyâ denâetdir. Birinci masdardan gelince, çok yakın demekdir. (Biz en yakın olan gökü, çırağlarla süsledik) âyet-i kerîmesindeki dünyâ kelimesi böyledir. Ba’zı yerde de, ikinci ma’nâ ile kullanılmışdır. Meselâ (Denî, alçak şeyler mel’ûndur) hadîs-i şerîfinde böyledir. Ya’nî (Dünyâ mel’ûndur) demekdir.","s":30},
  {"t":"Dünyâ","c":"Dünyâ, arabî bir kelimedir. Fen ilminde (En yakın şey) demekdir. Erd küresi, güneşden, aydan, yıldızlardan dahâ yakın olduğu için, Erd küresine dünyâ denir. Kıyâmetden önceki zemân, kıyâmetden sonraki zemândan dahâ yakın olduğu için, birincisine (Dünyâ hayâtı), ikincisine (Âhıret hayâtı) denir. Dünyâ kelimesinin din bilgisindeki ma’nâsı, (En zararlı, fenâ şey) demekdir.","s":78},
  {"t":"Dürzî","c":"DIRÂR: Mısrda, Fâtımîler zemânında bulunan bir yehûdî dönmesidir. Halîfe Hâkimi aldatdı. İslâmiyyeti yıkmağa uğraşdı. Bunun ve talebesi Hamzanın yolunda olanlara (Derezî) veyâ (Dürzî) denir.","s":1089},
  {"t":"Ecîr","c":"Mal sâhibine (Âcir) veyâ (Mûcir), kirâcıya ve işverene, ya’nî ücreti ödeyene, (Müste’cir), kendi kuvvetini veyâ san’atini kirâya verene, ya’nî çalışan kimseye (Ecîr) denir.","s":869},
  {"t":"Edâ","c":"Her cins nemâzı vaktinde kılmağa (Edâ) denir.","s":272},
  {"t":"Edâ etmek","c":"Bu üç kısm ibâdeti belli zemânlarda yapmağa (Edâ etmek) denir.","s":52},
  {"t":"Edille-i şer’ıyye","c":"Fıkh bilgileri, Kur’ân-ı kerîmden, hadîs-i şerîflerden, icmâ’-ı ümmetden ve kıyâsdan meydâna gelmekdedir. Fıkh bilgisinin bu dört kaynağına (Edille-i şer’ıyye) denir.","s":437},
  {"t":"Efsûn","c":"Ma’nâsı bilinmiyen veyâ küfre sebeb olan rukyeyi okumağa, (Efsûn) denir.","s":784},
  {"t":"Ehl-i kitâb","c":"Bir Peygambere ve bunun, sonradan bozulmuş olan (Mukaddes kitâb)ına inanan bir kâfir, bu Peygamber tanrıdır veyâ oğludur dese ve putlara yalvarırsa da, buna (Ehl-i kitâb) denir.","s":327},
  {"t":"Ehl-i sünnet","c":"Selef-i sâlihînin “rahmetullahi teâlâ aleyhim ecma’în” yolunda bulunan müslimânlara (Ehl-i sünnet) denir.","s":408},
  {"t":"Ehl-i sünnet âlimi","c":"Muhammed aleyhisselâm Allahü teâlânın bildirdiklerini Eshâbına bildirdi. Onlar da, talebelerine bildirdi. Bunlar da, kitâblarına yazdılar. Bu kitâbları yazan âlimlere (Ehl-i sünnet âlimi) denir.","s":2},
  {"t":"Ehl-i sünnet vel-cemâ’at mezhebi","c":"Üçüncü ve dördüncü asrlarda gelen islâm âlimlerine (Halef-i sâdıkîn) denir. Bu şerefli insanların i’tikâdına, (Ehl-i sünnet vel-cemâ’at mezhebi) denir.","s":492},
  {"t":"ekran","c":"Kutunun kapağının iç yüzü parlak bir levhadır. Bu levhaya (ekran) denir.","s":563},
  {"t":"Elektro-manyetik dalgalar","c":"Bir telden elektrik ceryânı geçince, telin etrâfında miknâtis dalgaları hâsıl olur. Bu dalgalara (Elektro-manyetik dalgalar) denir.","s":563},
  {"t":"Elektron","c":"Elektriğin, hiç bölünmiyen en küçük parçasına (Elektron) denir.","s":971},
  {"t":"Emânet","c":"(Mecelle)nin yediyüzaltmışikinci (762) maddesinde diyor ki: Güvenilen kimseye bırakılan mala (Emânet) denir.","s":605},
  {"t":"Emvâl-i bâtına","c":"Zekât mallarından altın, gümüş ve ticâret eşyâsına (Emvâl-i bâtına) denir.","s":309},
  {"t":"Emvâl-i zâhire","c":"İbni Âbidîn “rahmetullahi aleyh” buyuruyor ki: Dört nev’ zekât malından ikisine, ya’nî zekât hayvanları ile toprakdan elde edilen mallara (Emvâl-i zâhire) denir.","s":309},
  {"t":"Enelhak","c":"Hallâc-ı Mensûr, enelhak [ben Hakkım] dedi. Böylece, ben Hakkım, Hak teâlâ ile birleşdim demek istemedi. Böyle diyen kâfir olur ve öldürülmesi lâzım olur. Onun sözünün ma’nâsı, (Ben yokum, Hak teâlâ vardır) demekdir.","s":944},
  {"t":"Entorse","c":"(Nüzhet-ül-ebdân)da diyor ki, insan düşünce veyâ bir yere çarpınca, iğri basınca, oynak kemiği yerinden çıkar. Buna, (çıkık) denir. Fransızcada, (Luxation) denir. Yerinden oynar, fekat çıkmazsa (burkulma) veyâ (Entorse) denir.","s":675},
  {"t":"Erdin kutubları","c":"Bu mihver, Erdin merkezinden geçer ve Erdin sathını (yüzeyini) iki noktada delen bir doğrudur. Bu iki noktaya (Erdin kutubları) denir.","s":175},
  {"t":"Eshâb","c":"Resûlullahın “sallallahü aleyhi ve sellem” o güzel nûrlu yüzünü gören kimseye, (Sahâbî) denir. Birkaç dânesine (Eshâb) denir.","s":1046},
  {"t":"Eshâb-ı soffa","c":"Medîneli Ensârın fakîr olanları ile Muhâcirlerin fakîrleri, (Mescid-i nebî) yanındaki (Soffa) denilen büyük çardak altında yaşarlar, ilm öğrenmek ve öğretmekle uğraşırlar, ömrlerinin çoğu Resûlullah ile birlikde cihâd etmekle geçerdi. Bunlara (Eshâb-ı soffa) denirdi.","s":621},
  {"t":"Eshâb-ı şimâl","c":"Zulmânî, karanlık perdeler arkasında kalanlara, (Eshâb-ı şimâl) denir.","s":913},
  {"t":"Eshâb-ı yemîn","c":"Zulmânî, karanlık perdeler arkasında kalanlara, (Eshâb-ı şimâl) denir. Bu perdeleri aşıp, nûrdan perdeler gerisinde bulunanlara (Eshâb-ı yemîn) denir.","s":913},
  {"t":"Eski serây","c":"İstanbulu kuşatınca, yetmiş gemiyi Balta limanından kızaklarla karadan Kâsım pâşaya indirdi. Bir sene sonra Bâyezîd kulesinin olduğu yerde, ilk türk serâyını yapdırdı. Bu büyük serâya (Eski serây) denir.","s":1100},
  {"t":"Esmâ-i hüsnâ","c":"Kâdî zâde Ahmed efendi, (Birgivî vasıyyetnâmesi) şerhinde diyor ki, Allahü teâlânın doksandokuz ismine (Esmâ-i hüsnâ) denir.","s":431},
  {"t":"Espes pektoral","c":"Müsâvî mikdârda (sığır kuyruğu, gelincik, hatmi, kedi ayağı, deve tabanı ve menekşe) çiçekleri karışımına (Espes pektoral) denir.","s":673},
  {"t":"E’ûzü","c":"E’ûzü okumak, (E’ûzü billâhi mineşşeytânirracîm) demekdir.","s":3},
  {"t":"Evliyâ","c":"Halâl olsun, mubâh olsun, mâ-sivâyı, ya’nî Allahü teâlâdan başka herşeyi hâtırlamağı kalbinden çıkarmağa (Fenâ-fillah) denir. Buna kavuşan müslimâna (Velî) denir, (Evliyâ) denir.","s":78},
  {"t":"Eyyâm-ı teşrîk","c":"Kurban bayramının 2, 3 ve dördüncü üç gününe (Eyyâm-ı teşrîk) denir.","s":266},
  {"t":"Eyyâm-i nahr","c":"KURBAN BAYRAMI GECELERİ: Kurban bayramının birinci, ikinci ve üçüncü günlerinden sonraki gecelerdir. Bu üç güne (Eyyâm-i nahr) denir.","s":352},
  {"t":"Ezân-ı Cavk","c":"(İbni Âbidîn)de ve (Ukûd-üd-dürriyye)de diyor ki, Minârede ve Cum’a hutbesi okunacağı zemân, birkaç müezzinin birlikde ezân okumalarına (Ezân-ı Cavk) denir.","s":205},
  {"t":"Fadl-ı dâir=Zemân farkı","c":"Güneşin [merkezinin] meyli bilinen bir gündeki ve arz derecesi bilinen bir mahaldeki mahreki üzerinde, hakîkî üfka nazaran nemâzın irtifâ’ına ulaşdığı hakîkî vaktinin, zevâlden veyâ gece yarısından farkını bildiren hakîkî güneş zemânı hesâb edilir. Bu zemâna (Fadl-ı dâir=Zemân farkı) denir.","s":187},
  {"t":"Fakîh","c":"Fıkh bilgilerini bilen kimseye (Fakîh) denir.","s":437},
  {"t":"Farz","c":"(Redd-ül-muhtâr)da vitr nemâzını anlatırken diyor ki, İnanması da, yapması da farz olan emrlere (Farz) denir.","s":230},
  {"t":"Fâsid kan","c":"Üç günden, ya’nî yetmişiki sâatden, beş dakîka bile az olan ve yeni başlıyan için on günden çok sürünce, onuncu günden sonra ve yeni olmıyanlarda âdetden çok olup, on günü de aşınca, âdetden sonraki günlerde gelmiş olan ve hâmile ve âyise [ihtiyâr] kadınlardan ve dokuz yaşından küçük kızlardan gelen kanlar, hayz olmaz. Buna (İstihâza) veyâ (Fâsid kan) denir.","s":137},
  {"t":"Fâsid temizlik","c":"Onbeş veyâ dahâ ziyâde temiz gün içinde fâsid kan ya’nî istihâza kanı bulunursa, bu günlerin hepsine (Hükmî temizlik) veyâ (Fâsid temizlik) denir.","s":136},
  {"t":"Felse","c":"Fülûs, felsler demekdir. Bir felse, türkçede mangır, fârisîde (pul) denir.","s":796},
  {"t":"Felsefe","c":"Tecribeye, hesâba dayanmıyan şahsî düşüncelere (Felsefe) denirdi.","s":409},
  {"t":"Fen","c":"Fen (Mahlûkları, hâdiseleri görmek, inceleyip anlamak ve deneyip benzerini yapmak) demekdir ki, bu üçünü de, Kur’ân-ı kerîm emr etmekdedir.","s":1045},
  {"t":"Fenâ-fillah","c":"Halâl olsun, mubâh olsun, mâ-sivâyı, ya’nî Allahü teâlâdan başka herşeyi hâtırlamağı kalbinden çıkarmağa (Fenâ-fillah) denir.","s":78},
  {"t":"Fenâ makâmı","c":"Öyle bir hâl alır ki, bu akslerin aslı ve heyûlâsı gibi olan ademler, örtülmeğe, gayb olmağa başlar. Ya’nî sâlik, bunları göremez olur. Çünki, aynanın gayb olması lâzımdır. Bu hâle, (Fenâ makâmı) denir ve çok kıymetlidir.","s":912},
  {"t":"Fenâ-yi kalb","c":"Hakîkî sevgi pekçok olursa, sevdiğinden başka herşeyi unutur. Bu unutmağa (Fenâ-yi kalb) denir.","s":1056},
  {"t":"Fenâ-yi nefs","c":"Hakîkî sevgi pekçok olursa, sevdiğinden başka herşeyi unutur. Bu unutmağa (Fenâ-yi kalb) denir. Hattâ kendini de unutur. Kendini de unutmağa (Fenâ-yi nefs) denir.","s":1056},
  {"t":"Fen yobazı","c":"Fen adamlarının tecribelerini, sözlerini işitip de, kendi kurdukları yalanları, plânları, bu sözlerle maskeleyerek, gençleri zehrlemeğe, îmânlarını çalmağa uğraşan din hırsızlarına (Fen yobazı) denir.","s":542},
  {"t":"Ferâg etmek","c":"İmâm veyâ herhangi me’mûr, hava parası alarak, vazîfesini başkasına devr edebilir. Buna bey’ denmez. (Ferâg etmek) denir.","s":813},
  {"t":"Fey","c":"Muhârebe bitdikden sonra kâfirlerden zorla alınan mâla (Fey) denir.","s":577},
  {"t":"Fey-i zevâl","c":"En kısa gölge uzunluğuna (Fey-i zevâl) denir.","s":182},
  {"t":"Feyz","c":"Ültra viyole ışınlar, ciğerleri temizlediği gibi, kalb aynasını temizleyen, kalbi hastalıkdan kurtaran şuâ’lar da vardır. Bu şuâ’lara (Nûr), (Feyz) denir.","s":1049},
  {"t":"Fıkh ilmi","c":"Zarûrî lâzım olan, ya’nî (Zarûriyyât-i din) başkadır. Onlar, (İ’tikâd) ve (Amel) bilgileridir. Ya’nî, herşeyden önce, inanılacak bilgileri ve yapılacak vazîfeleri öğrenmek lâzımdır. Zarûrî bilgilerden birincisine (Kelâm ilmi), ikincisine (Fıkh ilmi) denir.","s":480},
  {"t":"Fısk meclisi","c":"Avret mahalli açık olan kimselerin bulunduğu yere veyâ harâm işlenen her yere (Fısk meclisi) denir.","s":169},
  {"t":"Fibrin","c":"Kesilen yerden çıkan kandaki fibrinogen, iplikler hâlinde pıhtılaşır. Bu pıhtıya (Fibrin) denir.","s":977},
  {"t":"Firâset","c":"Ümmet arasında, Velî olmıyanlardan meydâna gelen âdet dışı şeylere, (Firâset) denir.","s":748},
  {"t":"Fiyâtı","c":"(Bâyı’) ile (Müşterî) arasında uyuşulan değerine, (Pazarlık semeni) veyâ (Alış Semeni) veyâ (Fiyâtı) denir.","s":795},
  {"t":"Frekans=tekerrür","c":"Bir sâniyedeki dalga adedine (Frekans=tekerrür) denir.","s":548},
  {"t":"Fudûl","c":"Mubâhların fazlasına (Fudûl) denir.","s":428},
  {"t":"Fülûs","c":"Altından ve gümüşden başka ma’denlerden basılmış paralara, (Fülûs) denir.","s":796},
  {"t":"Gaben-i fâhiş=çok aldanmak","c":"(Mecelle)nin yüzaltmışbeşinci [165] maddesinde diyor ki, sarraflıkda piyasadaki fiyâtların en yükseğinden, yüzde ikibuçuk [% 2,5] ve dahâ fazlası kadar yüksek fiyâtla satın alarak aldanmağa (Gaben-i fâhiş=çok aldanmak) denir.","s":807},
  {"t":"Gaben-i yesîr=az aldanmak","c":"(Mecelle)nin yüzaltmışbeşinci [165] maddesinde diyor ki, sarraflıkda piyasadaki fiyâtların en yükseğinden, yüzde ikibuçuk [% 2,5] ve dahâ fazlası kadar yüksek fiyâtla satın alarak aldanmağa (Gaben-i fâhiş=çok aldanmak) denir. Bu mikdâr, urûz için, ya’nî hayvândan başka menkûl mallar için yüzde beş, hayvân için yüzde on, binâ için yüzde yirmidir. Bu mikdârlardan az olan aldanmağa, (Gaben-i yesîr=az aldanmak) denir.","s":808},
  {"t":"Gadab","c":"Allahü teâlâ, insanların ve hayvanların, yaşayabilmeleri ve üremeleri için, onlarda iki kuvvet yaratdı. Biri, muhtâc oldukları, lezzet aldıkları şeyleri istemek, onlara kavuşmak kuvvetidir. Bu kuvvete, (Şehvet) denir. İkincisi, yaşamalarına zarârlı olan, canlarını yakan şeylerden kaçmak, bunlara karşı savunmak kuvvetidir. Bu kuvvete, (Gadab) denir.","s":529},
  {"t":"Ganîmet","c":"Harbde kâfirlerden zorla alınan mala, (Ganîmet) denir.","s":577},
  {"t":"Gasb etmek","c":"(Hadîka)da el âfetlerinde diyor ki, Başkasının malını ondan iznsiz, zorla almağa, (Gasb etmek) denir.","s":536},
  {"t":"Gayb","c":"Görülüyor ki, islâm dîninin, hesâbın ve tecribenin bildirmediği şeylere (Gayb) denir.","s":782},
  {"t":"Gâye-i irtifâ’ı","c":"Üfkdan i’tibâren en yüksek olduğu vakt (zevâl vakti)dir. Bu vakt, güneşin (üfk-ı zâhirî hattından) olan yüksekliğine, güneşin (Gâye-i irtifâ’ı) denir.","s":175},
  {"t":"Geçici vatan","c":"Giriş ve çıkış günlerinden başka hanefîde onbeş, şâfi’î ve mâlikîde dört gün veyâ çok devâmlı kalıp, sonra çıkmağa niyyet edilen yere (Geçici vatan) denir.","s":225},
  {"t":"Gurup","c":"Her satıra, Devre [periyod] denir. Alt alta olan elemanların kimyâ hâssaları birbirinin aynıdır. Bunlara, yukardan aşağı, bir (Gurup) denir.","s":549},
  {"t":"Günâh","c":"Azâbların şiddetlerini, çokluğunu bildiren ölçü birimine, (İsm) ve (Günâh) denir.","s":681},
  {"t":"Günâhkâr","c":"Allahü teâlânın harâm etmesine ehemmiyyet verip, kabûl edip de, nefsine mağlûb olarak, aldanarak, bunları yapan ve sonra akllarını toparlayıp pişmân olanlar kâfir olmaz ve îmânlarını gayb etmezler. Böyle kimselere (Âsî) ve (Fâsık) [kötü kimse] denir ve (Günâhkâr) denir.","s":30},
  {"t":"Güneşin meyli","c":"Güneşin merkezi ile Ekvator sathı arasında kalan meyl dâiresi kavsinin derecesine (Güneşin meyli) denir.","s":177},
  {"t":"Haberci","c":"Bir kimsenin sözünü başkasına götürene (Resûl) veyâ (Haberci) denir.","s":834},
  {"t":"Haccetül-İslâm","c":"Farz olan hacca (Hacc-ı ekber) veyâ (Haccetül-İslâm) denir.","s":339},
  {"t":"Hacc-ı asgar","c":"Umreye (Hacc-ı asgar) denir.","s":339},
  {"t":"Hâdise, olay","c":"Cismlerde meydâna gelen değişmelere, (Hâdise, olay) denir.","s":971},
  {"t":"Hadîs-i kudsî","c":"Kelimeleri Peygamberimizden “sallallahü aleyhi ve sellem”, ma’nâları, Allahü teâlâdan olan hadîs-i şerîflere, (Hadîs-i kudsî) denir.","s":915},
  {"t":"Hadîs-i şerîf","c":"Muhammed aleyhisselâmın sözlerine (Hadîs-i şerîf) denir.","s":1043},
  {"t":"Hadîs müctehidi","c":"Üçyüzbinden dahâ çok hadîs-i şerîfi, râvîleri ile, senedleri ile birlikde ezber bilene (Hadîs imâmı) ve (Hadîs müctehidi) denir.","s":423},
  {"t":"Hafaza melekleri","c":"İnsanların iki omuzunda bulunup, iyiliklerini ve kötülüklerini yazan (Kirâmen kâtibîn) ismindeki iki melek ile, cinnîlerden koruyan meleklere, (Hafaza melekleri) denir.","s":240},
  {"t":"Hâfız","c":"Yüzbin hadîs-i şerîfi râvîleri ile birlikde, ezber bilene (Hâfız) denir.","s":1113},
  {"t":"hafî okumak","c":"Kendi kulakları işitecek kadar sesli okumağa, (hafî okumak) denir.","s":216},
  {"t":"Hakîkat","c":"Bundan sonra (Seyr-i fillah) denilen (İsbât) makâmına kavuşmak için çalışılır. Bu makâmda, kalb yalnız Allahü teâlâyı hâtırlamakdadır. Bu makâma (Bekâ) makâmı ve (Hakîkat) denir.","s":949},
  {"t":"Hakîkî gurûb","c":"Üç nev’i gurûb vardır: Şemsin merkezinin hakîkî irtifâ’ının sıfır olduğu vakte (Hakîkî gurûb) denir.","s":186},
  {"t":"Hakîkî gün","c":"Yine, zevâl vaktinde kol sâatimiz 12 iken başlıyarak, ertesi gün zevâl vaktine kadar geçen zemâna bir (Hakîkî gün) denir.","s":188},
  {"t":"Hakîkî güneş günü","c":"Güneş merkezinin, Nısf-ün-nehârdan iki geçişi, ya’nî iki hakîkî zevâl vakti arasındaki zemâna (Hakîkî güneş günü) denir.","s":183},
  {"t":"Hakîkî güneş sâati","c":"Hakîkî güneş gününün 24 de birine bir (Hakîkî güneş sâati) denir.","s":184},
  {"t":"Hakîkî irtifâ’ kavsi","c":"Güneşin merkezinden geçen semt dâiresinin, bu mahallin hakîkî üfkunu kesdiği semâdaki N noktası ile güneşin merkezi arasındaki GN kavs [yay] parçasına (Hakîkî irtifâ’ kavsi) denir.","s":177},
  {"t":"Hakîkî zevâl mahalli","c":"Râsıd en aşağı noktada iken, bütün üfuklara ve zâhirî üfuk hattına nazaran, zevâl mahalleri aynı bir noktadır ve güneşin günlük mahrekinin gündüz kısmının, nısf-ün-nehâr dâiresini kestiği nokta, 185.ci sahîfedeki şeklde gösterilen A noktası olup, mahrekin gündüz kısmının ortasıdır. Bu noktaya (Hakîkî zevâl mahalli) denir.","s":181},
  {"t":"Halâl","c":"Yasak edilmiş olmıyan, yâhud yasak edilmiş ise de, islâmiyyetin özr, mâni’ ve mecbûriyyet tanıdığı sebeblerden birisi ile yasaklığı kaldırılmış olan şeylere (Halâl) denir.","s":18},
  {"t":"Halef-i sâdıkîn","c":"Eshâb-ı kirâm ile Tâbi’în-i izâma (Selef-i sâlihîn) denir. Bunlardan sonra, hicretin dörtyüz senesi sonuna kadar gelen Ehl-i sünnet âlimlerine, (Halef-i sâdıkîn) denir.","s":1051},
  {"t":"Halîfe","c":"Bir islâm devletinin reîsine (Halîfe) denir.","s":1138},
  {"t":"Halîtan","c":"Kuru üzüm ve hurma birlikde, soğuk suda durup, hepsi, ısıtılıp süzülür. Tadı keskin olsa da, serhoş yapmadıkca, halâl olur. Buna, (Halîtan) denir.","s":625},
  {"t":"Halk","c":"İnsan birşeyi yapmağı veyâ terk etmeği ihtiyâr ve irâde eder ya’nî kuvvetini kullanır. Sonra, Allahü teâlâ da, bunu irâde eder, kudretini kullanırsa, bu şey olur. İlk ikisine (Kesb), son ikisine (Halk) denir.","s":702},
  {"t":"Harac","c":"Bir farzın yapılmasına mâni’ veyâ harâm işlemeğe sebeb olanı önlemenin meşakkatli, güç olmasına (Harac) denir.","s":135},
  {"t":"Harâm","c":"Allahü teâlânın emrlerine (Farz), yasak etdiği şeylere (Harâm) denir.","s":98},
  {"t":"Hareket-i hakîkiyye","c":"Ya’nî, masa üstüne konan bir Erd küresine yukarıdan bakınca, şimâl memleketlerinde, sâat ibreleri hareketinin ters cihetine doğru dönmekdedir. Buna (Hareket-i hakîkiyye) denir.","s":183},
  {"t":"Hareket-i ric’ıyye","c":"Güneşin ve sâbit yıldızların, şarkdan garba doğru, Erd küresi etrâfında hergün bir devr yapdıkları görülür. Buna (Hareket-i ric’ıyye) denir.","s":183},
  {"t":"Haremeyn-i şerîfeyn","c":"Mekke ve Medîne şehrlerine (Haremeyn-i şerîfeyn) denir.","s":343},
  {"t":"Harem-i şerîf","c":"Mescid-i harâma (Harem-i Kâ’be) veyâ (Harem-i şerîf) denir.","s":343},
  {"t":"Hâricî","c":"Hazret-i Alînin askerinden ayrılarak, ona karşı harb edenler böyle idi. (Hâkim ancak Allahdır. Hazret-i Alî, iki hakemin hükmüne uyarak, [hilâfeti Mu’âviyeye bırakmakla] büyük günâh işledi. Büyük günâh işleyen kâfir olur) dediler. Onunla harb etmelerine bu yanlış te’vîlleri sebeb oldu. Kendileri gibi inanmıyanlara kâfir dediler. Bunlara (Hâricî) denir.","s":472},
  {"t":"Hârizm","c":"Hazer gölünün şarkındaki Aral gölünün şark tarafına, şimâlde Seyhûn, cenûbda Ceyhûn nehrleri, şimâl-i garbîye doğru akarlar. İki nehr arasına (Mâ-verâ-ün-nehr) denir. İki göl arasının cenûb kısmına (Hârizm) denir.","s":431},
  {"t":"Hâs","c":"Askerin toprağına (Timar), subay toprağına (Ze’âmet), general toprağına (Hâs) denirdi.","s":305},
  {"t":"Hatîm","c":"Yerde bu oluk hizâsında kavs şeklindeki dıvarcık ile Kâ’be-i mu’azzama arasında kalan yere (Hatîm) denir.","s":348},
  {"t":"Havârî","c":"Kendisinden sonra Îsevîliği dünyâya yaymak için, Eshâbı arasından seçdiği oniki mü’mine (Havârî) denir.","s":1108},
  {"t":"Havra","c":"Yehûdîlerin ma’bedlerine (Sinagog) ve (Havra) denir.","s":244},
  {"t":"Hayz","c":"(Hayz), akmak demekdir. Sekiz yaşını bitirip, dokuz yaşına basdıkdan birkaç gün veyâ ay, yâhud seneler sonra, sıhhatli bir kızın veyâ âdet zemânı son dakîkasından i’tibâren (Tam temizlik) geçmiş olan kadının önünden çıkan ve en az üç gün, ya’nî ilk görülmesinden i’tibâren yetmişiki mu’tedil ya’nî vasatî sâat devâm eden kana denir.","s":136},
  {"t":"Hayz kanı (Mâlikî mezhebinde)","c":"Mâlikî mezhebinde, dokuz yaşına gelmiş kızın önünden, bir sebeb olmadan akan kırmızı, sarı veyâ bulanık kana (Hayz kanı) denir.","s":889},
  {"t":"Hek","c":"Bunlardan başkasının (Sünen) kitâbı söylenirken, yazarının da adı birlikde söylenir. Meselâ, (Sünen-i Dâre Kutnî) (KTın) ve (Sünen-i kebîr-i Beyhekî) (Hek) denir.","s":424},
  {"t":"Herşey Odur","c":"Bundan anlaşıldı ki, sôfiyye, eşyâya, Hak teâlâdan meydâna gelmişdir, Hak teâlâ değildir diyor. O hâlde, sôfiyyenin (Herşey Odur) sözleri, (Herşey Ondandır) demekdir ki, âlimler de böyle söylemekdedir.","s":944},
  {"t":"Hicret","c":"Târîhcilere göre mîlâdın 622 senesinde, Allahü teâlânın emri ile, Mekkeden Medîneye gitdi. Bu yolculuğuna (Hicret) denir.","s":1139},
  {"t":"Hil","c":"(Mîkât) denilen yerler ile, Harem-i Mekke arasına (Hil) denir.","s":343},
  {"t":"Hîle-i şer’ıyye","c":"Böyle, farzı yapmamakdan veyâ harâm işlemekden kurtuluş yolu aramağa (Hîle-i şer’ıyye) denir.","s":859},
  {"t":"Hisbet","c":"Emr-i ma’rûfu ve Nehy-i münkeri el ile yapmak, devlet adamlarına, dil ile yapmak, din adamlarına, kalb ile yapmak da her müslimâna farzdır. El ile yapmağa (İhtisâb) ve (Hisbet) denir.","s":885},
  {"t":"Hisse-i fecr","c":"Fecr vakti ile tulû’ vakti arasındaki zemâna (Hisse-i fecr) denir.","s":198},
  {"t":"Hisse-i şafak","c":"Şafak vakti ile gurûb vakti arasındaki zemâna (Hisse-i şafak) denir.","s":198},
  {"t":"Hisse-i şâyı’a sâhibi","c":"Bir binâya ortak olarak mâlik olan kimselere, (Hisse-i şâyı’a sâhibi) denir.","s":818},
  {"t":"Huccet-ül-islâm","c":"İkiyüzbin hadîs-i şerîfi ezbere bilene (Şeyh-ul-hadîs) denir. Üçyüzbin ezberliyene, (Huccet-ül-islâm) denir.","s":423},
  {"t":"Hudûr","c":"Allahü teâlâ ile olmağa, (Hudûr) denir ki, hadîs-i şerîfde bildirilen (İhsân) mertebesidir.","s":768},
  {"t":"Hukemâ","c":"Din bilgilerini, fen bilgileri ile isbât eden mü’minlere (Hukemâ) denir.","s":1043},
  {"t":"Hurûf-i cümmel","c":"(Ebced hevvez huttî) kelimelerindeki harflere (Hurûf-i cümmel) denir.","s":359},
  {"t":"Işıma","c":"Şuâ’: Sulb, ya’nî katı veyâ mâyı’ hâldeki bir madde ısıtılırsa, beşyüz derecede zıyâ [ışık] yaymağa başlar ve madde değişmez. Evvelâ kırmızı zıyâ olur. Dahâ sıcakda beyâza döner. Elektrik ampullerinde, elektrik ceryânı, ampul telini ısıtdığı için, tel zıyâ yayar. Böyle zıyâ yaymağa (Şuâ’lanma) veyâ (Işıma) denir.","s":548},
  {"t":"Iyâl","c":"Kendilerine nafaka verilmesi vâcib olanlara (Iyâl) denir.","s":789},
  {"t":"İâde","c":"Bir nemâzı vakti içinde tekrâr kılmağa (İâde) denir.","s":272},
  {"t":"İbâdet etmek","c":"İhlâs ile, ya’nî Allahü teâlânın rızâsına, sevgisine kavuşmak ve sevâb kazanmak niyyeti ile, farzları, sünnetleri yapmağa ve harâmlardan ve mekrûhlardan kaçınmağa, ya’nî ahkâm-ı islâmiyyeyi yerine getirmeğe (İbâdet etmek) denir.","s":20},
  {"t":"İbâdethâne","c":"İbâdet yapmak için, toplanılan yerlere (Ma’bed) veyâ (İbâdethâne) denir.","s":244},
  {"t":"Îcâb","c":"Alıcı ve satıcıdan, râzı olduğunu hangisi önce söylerse, buna (Îcâb) denir.","s":792},
  {"t":"İcmâ’-ı ümmet","c":"Selef-i sâlihînin söz birliğine (İcmâ’-ı ümmet) denir.","s":437},
  {"t":"İctihâd","c":"Açıkca emr veyâ yasak edilmemiş işler ise, böyle değildir. Böyle işleri yapıp yapmamakda, açıkca bildirilenlere benzetilmelerini, Allahü teâlâ, derin âlimlere emr etmekdedir. Bu benzetmeyi yapabilecek derin âlimlere (Müctehid) denir. Bu benzetmek işine, (İctihâd) denir.","s":464},
  {"t":"İctimâ’ı neyyireyn=Conjunction","c":"Her devrinde, bir kerre, ay ile güneş, yer küresinin aynı tarafında olarak, üçü bir doğrultuda bulunuyorlar. Bu hâle (İctimâ’ı neyyireyn=Conjunction) denir.","s":360},
  {"t":"İhtikâr","c":"Bir şehre dışardan gelen gıdâ ve ihtiyâc eşyâsını, şehr hâricinde karşılayarak ucuz alıp, şehrde depo ederek pahâlı satmak harâmdır. Buna (İhtikâr) denir.","s":813},
  {"t":"İhtiyâc maddeleri","c":"İnsanın ba’zı arzûları, tabî’atinden ileri gelmekdedir. Beden sağ kaldıkca, hiç kimse bu isteklerden kurtulamaz. Meselâ, harâret artınca, insanın tabî’ati serin birşey içmek ister. Soğukda, sıcak birşey ister. Böyle istekleri yapmak günâh değildir ve nefse uymak değildir. Çünki, tabî’atimizin zarûrî istekleri mubâhdır. Bunlara (ihtiyâc maddeleri) denir.","s":647},
  {"t":"İhtiyât zemânı","c":"İmsâkin iki vakti arasındaki [On dakîka kadar] zemâna (İhtiyât zemânı) denir.","s":316},
  {"t":"İkinci nev’","c":"Kur’ân-ı kerîmde açıkca emr edilmiş olan, yukarıda, ikinci numarada yazılı, altı farzdan, nısf, rubu’, sümün cinslerine (Birinci nev’), sülüsân, sülüs ve südüs cinslerine (İkinci nev’) denir.","s":1030},
  {"t":"İkinci sınıf bileşikler","c":"İçinde üç element bulunan anorganik bileşiklere, (İkinci sınıf bileşikler) denir.","s":547},
  {"t":"İllet","c":"Her şeyin vücûdü, ya’nî var olması, bir işin yapılmasına bağlıdır. Bu bağlılık, beş dürlü olur: İş, bu şeyin mâhiyyetinin içinde ise, onun bir parçası ise, bu işe, (Rükn) denir. Dışında ise, bu şeye te’sîr ediyorsa, (İllet) denir.","s":122},
  {"t":"İlm-i ferâiz","c":"Vefât eden kimsenin bırakdığı malın kimlere verileceğini ve nasıl dağıtılacağını öğreten ilme, (İlm-i ferâiz) denir.","s":1025},
  {"t":"İlm-i fıkh","c":"Beden ile yapılacak ahkâm-ı islâmiyyeyi bildiren ilme (İlm-i fıkh) denir.","s":103},
  {"t":"İlm-i kelâm","c":"Îmân ve i’tikâd aynıdır. Bunları anlatan geniş ve derin ilme (İlm-i kelâm) denir.","s":103},
  {"t":"İlm-ül-yakîn","c":"(Müceddidiyye) büyükleri, [ya’nî, imâm-ı Rabbânî talebelerinden tâ bu zemâna kadar gelenler] buyurdular ki, murâkabe ve zikr ederken, keyfiyyetlerin, hâllerin ve nûrların hâsıl olmasına (İlm-ül-yakîn) denir.","s":765},
  {"t":"Îmân","c":"Resûlullahın “sallallahü aleyhi ve sellem” söylediklerinin hepsini beğenip kalbin kabûl etmesine, ya’nî inanmasına (Îmân) denir.","s":17},
  {"t":"Îmân-ı şühûdî","c":"Dâire, noktanın görünmesini örtüyor denirse yeri vardır. Dâire, noktanın varlığını gösteren bir ayna gibidir denirse, yine doğru olur. Eğer noktanın varlığına alâmetdir denirse, yine olur. Noktayı örtüyor demek, câhillerin sözüdür. Aynadır demek Evliyâlığa uygundur ve buna (Îmân-ı şühûdî) denir.","s":931},
  {"t":"İnhitât-ı üfuk zâviyesi","c":"Sathî üfka nazaran olan ZS irtifâ’ından hakîkî irtifâ’dan ZN in farkına, M yüksekliği için (İnhitât-ı üfuk zâviyesi) denir.","s":181},
  {"t":"İnşikak","c":"Uranium 235 atomunun bu sûretle parçalanmasına fission (inşikak=yarılma) denir ki, Radioaktiviteye hiç benzemiyor.","s":554},
  {"t":"İnternet","c":"Ara merkezlerde bulunan bilgisayar, ya’nî (computer)lerin bir uydu vâsıtası ile, semâya gönderdikleri elektro-manyetik dalgaların fezâdaki topluluğuna (İnternet) denir.","s":563},
  {"t":"İrtifâ’ dâireleri","c":"Semt düzlemlerinin semâ küresini kesdiklerini düşünürsek, küre sathında hâsıl etdikleri bu dâirelere, o mahallin (Semt dâiresi=Azimut)leri veyâ (İrtifâ’ dâireleri) denir.","s":177},
  {"t":"İrtifâ’ zâviyesi","c":"İlk üç irtifâ’ın toplamından (İhtilâf-ı manzar) mikdârı olan 8,8 sâniye çıkarılınca, bir derece 29 dakîka 6,2 sâniye olur ki, buna güneşin (İrtifâ’ zâviyesi) denir.","s":186},
  {"t":"İslâm âlimi","c":"İslâmiyyetin temeli üçdür: İlm, amel ve ihlâs. 1– İlm, Ehl-i sünnet âlimlerinin kitâblarından öğrenilir. 2– İlme uygun olan ameldir. 3– İlmde ve amelde ihlâs sâhibi olmakdır. İhlâs, ilmin ve amelin Allah rızâsı, Allah sevgisi ile olmasıdır. Mal, mevkı’ ve şöhret için olmamasıdır. Bu üçüne sâhib olan müslimâna (Hakîkî müslimân) ve (İslâm âlimi) denir.","s":16},
  {"t":"İslâm bilgileri","c":"Fâideli ilm, se’âdet-i ebediyyeyi elde etmeğe, ya’nî Allahü teâlânın rızâsını kazanmaya vesîle olan ilmdir ki, bunlara, (İslâm bilgileri) denir.","s":260},
  {"t":"İslâmiyyet","c":"Hem nefsin arzûlarına uymağı sınırlıyan, hem de nefsi temizleyip emmârelikden ya’nî aşırı, taşkın olmakdan kurtaran emrler ve yasaklar gönderdi. Peygamberleri “aleyhimüssalevâtü vetteslîmât” ile gönderdiği bu emr ve yasakların toplamına, (İlâhî din)ler veyâ (İslâmiyyet) denir.","s":529},
  {"t":"İsmâ’îlî","c":"Yedinci imâm İsmâ’îldir ve ondan sonra çocuklarıdır diyen sapıklara (İsmâ’îlî) denir.","s":1084},
  {"t":"İstidlâlî","c":"Akl ile bilmek de ikidir: Düşünmeden hemen bilinirse, (Bedîhî) denir. Düşünmekle bilinirse, (İstidlâlî) denir.","s":782},
  {"t":"İstidrâc","c":"Ümmet arasında, Velî olmıyanlardan meydâna gelen âdet dışı şeylere, (Firâset) denir. 4 — Fâsıklardan, günâhı çok olanlardan zuhûr ederse (İstidrâc) denir ki, derece derece, kıymetini indirmek demekdir.","s":748},
  {"t":"İstigfâr etmek","c":"Günâhlarını afv etmesi için Allahü teâlâya yalvarmağa (İstigfâr etmek) denir.","s":64},
  {"t":"İstinşâk","c":"Burnu, ayrı ayrı su ile, üç kerre yıkamak. Buna (İstinşâk) denir.","s":122},
  {"t":"İşrâkıyyun","c":"PİSAGOR: Eski yunan filosofudur. Bunun felsefesine (İşrâkıyyun) denir.","s":1161},
  {"t":"İ’tibâr ediniz","c":"(Ey ilm sâhibleri! İ’tibâr ediniz!) âyet-i kerîmesi, (Bilmediklerinizi, bildiklerinize kıyâs ediniz!) demekdir.","s":474},
  {"t":"İyon","c":"Elektrik yükü taşıyan atomlara (İyon) denir.","s":547},
  {"t":"İyon şebekesi","c":"İki veyâ ziyâde elementin atom iyonları, boşlukda, sıra ile dizilir. Böyle milyonlarla iyon yığını, bir cism meydâna getirir. Böyle bir cism, bir sandık kesme şekere benzer. Bunlara, (İyon şebekesi) denir.","s":547},
  {"t":"İzotop","c":"İzotop, yunanca (aynı yer) demekdir.","s":554},
  {"t":"Kabûl","c":"Alıcı ve satıcıdan, râzı olduğunu hangisi önce söylerse, buna (Îcâb) denir. İkincisinin sözüne, (Kabûl) denir.","s":792},
  {"t":"Kader","c":"Dünyâda yapılan her işden ve düşünceden, dünyâda ve âhıretde fâide veyâ zarar hâsıl olur. Fâide hâsıl olanlara (Hayr), zarar hâsıl olanlara (Şer) denir. Allahü teâlâ, hayrları, şerlerden ezelde ayırmışdır. Bunlar, birbirleri ile hiç karışmaz. Bu ayırmağa, (Kazâ) ve (Kader) denir.","s":697},
  {"t":"Kâfir","c":"Fekat, Kur’ân-ı kerîmde ve hadîs-i şerîflerde açıkca bildirilen ve müslimânların asrlar boyunca inandığı bir şeye uymıyan söz ve işde bulunan bir kimse, bütün ömrünce nemâz kılsa, her ibâdeti yapsa da, buna (Kâfir) denir.","s":252},
  {"t":"Kalb-i hakîkî","c":"Kalb, ya’nî gönül, sol memenin altında ve iki parmak aşağıda, yürek denilen bir parça etde bulunan nûrdan bir kuvvetdir. Yürek, yumurta veyâ kozalak gibidir. Buna, (Kalb-i sanevberî) denir. Burada bulunan nûrdan kuvvete, (Kalb-i hakîkî) denir.","s":922},
  {"t":"Kalb-i sanevberî","c":"Kalb, ya’nî gönül, sol memenin altında ve iki parmak aşağıda, yürek denilen bir parça etde bulunan nûrdan bir kuvvetdir. Yürek, yumurta veyâ kozalak gibidir. Buna, (Kalb-i sanevberî) denir.","s":922},
  {"t":"Kalender","c":"Melâmîlerin doğru taklîdcileri, ibâdetlerinin görünmesine ehemmiyyet vermezler. Âdetlere uyarlar. Herkese tatlı söyliyerek, gülerek kalb kazanmağa uğraşırlar. Nâfile ibâdetleri yapmazlar. Farzlara dikkat ederler. Dünyâya düşkün değildirler. Bunlara, (Kalender) denir.","s":486},
  {"t":"Kansızlık","c":"Hâlsizlik, baş ağrısı, kulak çınlaması, kalb çarpıntısı, el, ayak soğuması olur. Bu hâle anemi (Kansızlık) denir.","s":977},
  {"t":"Karbonhidrat","c":"Şekerli ve nişastalı her madde yasakdır. Bunlara (karbonhidrat) denir.","s":658},
  {"t":"Kâri’","c":"Kur’ân-ı kerîmi ezberliyene hâfız denmez, (Kâri’) denir.","s":423},
  {"t":"Karz-ı hasen","c":"Çarşıda misli, ya’nî benzeri bulunan herşeyi, belirsiz bir zemân sonra, misli geri verilmek üzere vermeğe, (Karz-ı hasen) denir.","s":824},
  {"t":"Katod şuâ’ları","c":"Borudaki gaz, dahâ boşaltılıp, tazyîkı dahâ azalırsa, ışık da azalır ve bir ân gelir ki, borunun içi zıyâsız kalır. Fekat şimdi, makaranın (—) kutbuna bağlı katodun tam karşısındaki cam üzerinde mâvi renklenme görülür. Demek ki, katoddan, görülemiyen şuâ’lar çıkmakdadır. Bunlara, (Katod şuâ’ları) denir.","s":549},
  {"t":"Katyon","c":"Artı elektrik taşıyan atomlara (Katyon) denir.","s":547},
  {"t":"Kazâ","c":"Bir nemâzı vakti içinde tekrâr kılmağa (İâde) denir. Vaktinde kılınmazlarsa, vaktinden sonra kılmağa (Kazâ) denir.","s":273},
  {"t":"Kazâ etmek","c":"Zemânında yapmayıp, zemân geçdikden sonra yapmağa (Kazâ etmek) denir.","s":52},
  {"t":"Kefîr","c":"Kısrak, inek, deve sütleri, mayalanıp, tadı keskin olunca, müselles gibi olurlar. Birincisine (Kumis) [kımız], diğer ikisine (Kefîr) denir.","s":625},
  {"t":"Kelime-i temcîd","c":"İmâm-ı Rabbânî hazretleri, yüzyetmişdördüncü mektûbunda, Cini def’ için bunu okumağı tavsiye etmekdedir. Buna, (Kelime-i temcîd) denir.","s":741},
  {"t":"Kerâhet zemânı","c":"NEMÂZ KILMASI TAHRÎMEN MEKRÛH, YA’NÎ HARÂM OLAN ZEMÂN ÜÇDÜR: Bu üç vakte, (Kerâhet zemânı) denir.","s":201},
  {"t":"Kerâmet","c":"Peygamberlerin “aleyhimüsselâm” ümmetlerinin Evliyâsında, nefslerinin kötülükleri kalmadığı için âdet dışı meydâna gelen şeylere, (Kerâmet) denir.","s":747},
  {"t":"Kesb","c":"Kalbin, iyiden, kötüden birini ihtiyâr ve irâde etmesine (Kesb) denir.","s":32},
  {"t":"Kıble açısı","c":"Güneş bu hat üzerine gelince, (Kıble sâati) olur. Bu hat ile bu şehrden geçen tûl dâiresi arasındaki zâviyeye (Kıble açısı) denir.","s":170},
  {"t":"Kıble hattı","c":"Harîta üzerinde bir şehr ile, Mekke şehri arasında çizilen doğruya (Kıble hattı) denir.","s":170},
  {"t":"Kıble zâviyesi","c":"İstanbulun kıble istikâmeti, cenûbdan yirmidokuz derecelik bir zâviye [açı] kadar şarkdadır. Bu açıya (Kıble zâviyesi) denir.","s":170},
  {"t":"Kırâet-i şâzze","c":"(Rıyâd-ün-nâsıhîn)de diyor ki: Arabî gramer şartlarına uyan ve ma’nâyı değişdirmiyen, fekat ba’zı kelimeleri Osmân radıyallahü anhın topladığına benzemiyen Kur’ân-ı kerîme (Kırâet-i şâzze) denir.","s":47},
  {"t":"Kıyâs-ı fükahâ","c":"Kur’ân-ı kerîmden veyâ hadîs-i şerîflerden veyâ icmâ’-ı ümmetden çıkarılan ahkâm-ı islâmiyyeye (Kıyâs-ı fükahâ) denir.","s":437},
  {"t":"Kıymet","c":"Mebî’in piyasadaki fiyâtına, değeri (kıymeti) denir.","s":795},
  {"t":"Kinâye","c":"(Babanın evine git!), (Benden git, murâdına er), (Örtün!), (Başını ört!), (Sen hürsün!), (Kendine koca ara!), (Cehenneme git!), (Sen bana hınzır gibisin), (Senin zevcin değilim), (Ben senden ayrıyım), (Sen benden bâinsin) gibi, başka yerlerde de kullanılan sözü, boşamak niyyeti ile söyleyince, veyâ (Sen bana harâmsın) deyince, bir talâk-ı bâin vâkı’ olur. Böyle, birkaç ma’nâda kullanılan kelimelere, (Kinâye) denir.","s":580},
  {"t":"Kirâ, ücret","c":"İcâre, bir malın, kendini değil de, menfe’atini ya’nî kullanılmasını satmak olup, kirâya vermek demekdir. Îcâb ve kabûl ile yapılır. Bu satışın semenine (Kirâ, ücret) denir.","s":869},
  {"t":"Komünizm","c":"İhtilâlci sosyalizme (Komünizm) denir.","s":523},
  {"t":"Kurbet","c":"Bir kimse Allahü teâlâ için yapdığını bilerek tâ’at yaparsa, buna (Kurbet) denir.","s":19},
  {"t":"Kureyşî","c":"FİHR: Resûlullahın onbirinci babasıdır. Mâlikin oğlu, Gâlibin babasıdır. Fihr, avuc dolusu taş demekdir. İsmi Kureyşdir. Bunun soyundan olanlara (Kureyşî) denir.","s":1101},
  {"t":"Kuru üzüm nakî’i","c":"Kuru üzüm, soğuk suda bırakılınca, şekeri suya geçer. Bu suya, (Kuru üzüm nakî’i) denir.","s":624},
  {"t":"Kutb-i medâr","c":"Tesavvuf yolunda nihâyete varanlar “rahmetullahi teâlâ aleyhim ecma’în” iki dürlüdür: Birincisi, Resûlullahın “sallallahü aleyhi ve sellem” izinde giderek kemâle erdikden sonra, insanları gafletden uyandırmak için, halk derecesine indirilmiş olanlardır. İkincisi, yükseldikleri derecelerde bırakılıp, insanların yetişmesi ile vazîfeli olmıyan (Evliyâ)dır “rahmetullahi teâlâ aleyhim ecma’în”. Bunlara, (Kutb-i medâr) denir.","s":486},
  {"t":"Kuvvet","c":"Duran bir cismi harekete getiren, hareketde olan bir cismi durduran veyâ hareketini değişdiren sebebe (Kuvvet) denir.","s":1041},
  {"t":"Kübrâ","c":"Her cism [maddeler, atomlar] değişmekdedir. Değişen şeyler, hâdisdir [yok iken var olmuşdur]. O hâlde, âlem hâdisdir. Bu üç cümleden ilk ikisi mukaddemedir. Mantık ilminde, birincisine (Sugrâ), ikincisine (Kübrâ) denir.","s":759},
  {"t":"Küfr","c":"Onun sözlerinden birine bile inanmamağa veyâ iyi ve doğru olduğunda şübhe etmeğe (Küfr) denir.","s":17},
  {"t":"Küfr-i cehlî","c":"Eğer, küfre sebeb olduğunu bilmeyip söyler, yaparsa veyâ küfre sebeb olacağı, âlimler arasında ihtilâflı olan bir sözü amden söylerse, îmânının gideceği ve nikâhının bozulacağı, şübhelidir. İhtiyât olarak, tecdîd-i îmân ve nikâh etmesi iyi olur. Bilmiyerek söylemeğe (Küfr-i cehlî) denir.","s":436},
  {"t":"Küfr-i hükmî","c":"Bunlardan meşhûr olanlarını bilmiyerek veyâ şaka olarak veyâ herkesi güldürmek için yapan da, kâfir olur. Meselâ, papasların ibâdetlerine mahsûs şeyi kullanmak küfr olur. Buna (Küfr-i hükmî) denir.","s":53},
  {"t":"Küfr-i inâdî","c":"Erkek veyâ kadın, bir müslimân, âlimlerin sözbirliği ile küfre sebeb olacağını bildirdikleri bir sözün veyâ işin küfre sebeb olduğunu bilerek, amden [tehdîd edilmeden, istekle] ciddî olarak veyâ hezl, güldürmek için söyler, yaparsa, ma’nâsını düşünmese dahî îmânı gider. (Mürted) olur. Buna (Küfr-i inâdî) denir.","s":436},
  {"t":"Kütüb-i sitte","c":"Doğru oldukları, bütün islâm âlimleri tarafından tasdîk edilmiş olan hadîs kitâblarından altı dânesi, bütün dünyâda şöhret bulmuşdur. Bu altı kitâba (Kütüb-i sitte) denir.","s":423},
  {"t":"Kvant","c":"Şuâ’ enerjisinin, bölünemiyen en küçük parçasına (Kvant) denir.","s":548},
  {"t":"Lenfatik lösemi","c":"Bilemediğimiz bir sebeble, kanda lökosit çoğalmasına (Lösemi) kan kanseri denir. Lökosit artması fazla ise, (Miyole lösemi) denir. Lenfosit artması dahâ çok ise (Lenfatik lösemi) denir.","s":977},
  {"t":"Lipotropik","c":"Karaciğerde yağ toplanmasını azaltan ve yağları ciğerden çıkaran maddelere (Lipotropik) denir.","s":654},
  {"t":"Livâta","c":"Puştluk, ya’nî cinsî sapıklık denilen oğlan kirletmek dahâ büyük günâhdır. Buna (Livâta) denir.","s":140},
  {"t":"Luxation","c":"(Nüzhet-ül-ebdân)da diyor ki, insan düşünce veyâ bir yere çarpınca, iğri basınca, oynak kemiği yerinden çıkar. Buna, (çıkık) denir. Fransızcada, (Luxation) denir.","s":675},
  {"t":"Madde","c":"Fen dersleri bildiriyor ki, ağırlığı ve hacmi olan varlıklara (Madde) denir.","s":1041},
  {"t":"Malt","c":"Arpalar kurutulup un yapılır. Bu una, (Malt) denir.","s":625},
  {"t":"Maraz-ı mevt","c":"Bir sene içinde ölüme sebeb olan hastalığa, (Maraz-ı mevt) denir.","s":816},
  {"t":"Ma’rifet","c":"Din bilgileri de ikiye ayrılır: Zâhirî ilmler ve bâtınî ilmler. Birincilere, (Îmân bilgileri) ve (Fıkh bilgileri) veyâ (Ahkâm-ı islâmiyye), ikincilere (Tesavvuf bilgileri) veyâ (Ma’rifet) denir.","s":25},
  {"t":"Mâ-verâ-ün-nehr","c":"Hazer gölünün şarkındaki Aral gölünün şark tarafına, şimâlde Seyhûn, cenûbda Ceyhûn nehrleri, şimâl-i garbîye doğru akarlar. İki nehr arasına (Mâ-verâ-ün-nehr) denir.","s":431},
  {"t":"Mazmaza","c":"Ağzı, ayrı ayrı su ile, üç kerre yıkamak. Buna (Mazmaza) denir.","s":122},
  {"t":"Mehr-i mu’accel","c":"Mehr iki kısmdır. Birincisinin verilmesi, nikâh yapılınca vâcib olur ve yarısı veyâ hepsi sâkıt olabilir. Buna, (Mehr-i mu’accel) denir.","s":568},
  {"t":"Mehr-i müeccel","c":"Mehr iki kısmdır. Birincisinin verilmesi, nikâh yapılınca vâcib olur ve yarısı veyâ hepsi sâkıt olabilir. Buna, (Mehr-i mu’accel) denir. İkincisinin mikdârı da nikâh yapılırken belli edilir ise de, verilmesi, üç şeyden biri hâsıl olunca vâcib olur ve hiçbir sebeble azalmaz. Buna, (Mehr-i müeccel) denir.","s":568},
  {"t":"Mekrûh","c":"Allahü teâlânın, açıkca bildirmeyip, yalnız Peygamberimizin “sallallahü aleyhi ve sellem” yapılmasını övdüğü, yâhud devâm üzere yapdığı, yâhud yapılırken görüp de mâni’ olmadığı şeylere (Sünnet) denir. Sünneti beğenmemek küfrdür. Beğenip de yapmamak suç değildir. Onun beğenmediği şeylere ve ibâdetin sevâbını gideren şeylere (Mekrûh) denir.","s":18},
  {"t":"Menâsik","c":"Hac, lügatda, kasd etmek, yapmak, istemek demekdir. İslâmiyyetde, belli bir yeri, belli bir zemânda, belli şeyleri yaparak ziyâret etmek demekdir. Bu belli şeylere (Menâsik) denir.","s":339},
  {"t":"Menkûl","c":"Bir yere götürülmesi mümkin olan mala (menkûl) denir.","s":792},
  {"t":"Mer’î vakt","c":"Güneşin bir mer’î vakte geldiği, bu riyâdî vaktden 8 dakîka 20 sâniye sonra görülür ki, buna (Mer’î vakt) denir.","s":176},
  {"t":"Mesânîd","c":"Meşhûr ve çok kıymetli hadîs kitâblarından, imâm-ı Ahmed bin Hanbelin (Müsned)i (HD) ve Ebû Ya’lâ (Müsned)i (Ya’lâ) ve Abdüllah Dârimînin (Müsned)i (DR) ve Ahmed Bezzârın (Müsned)i (Z) ile gösterilir. Bu kitâblara (Mesânîd) denir.","s":424},
  {"t":"Mesbûk","c":"İmâma birinci rek’atde yetişemiyen kimseye (Mesbûk) denir.","s":233},
  {"t":"Meskûkât","c":"(Mir’ât-ül-haremeyn)in Mekke kısmında diyor ki, Belli ağırlıkda basılmış olan altın ve gümüş paralara, (Meskûkât) denir.","s":802},
  {"t":"Mevdû’","c":"Süyûtî, Zehebî ve Askalânî gibi hadîs âlimleri, birkaç hadîs-i şerîfe mevdû’ demişler ise de, bu sözleri, (Benim mezhebimdeki sahîh olmak şartları yokdur) demekdir.","s":442},
  {"t":"Mevdû’","c":"Üsûl-i hadîs âlimleri, bir hadîsin sahîh olması için koydukları şartları taşımıyan bir hadîse (Mevdû’) der ki, (Benim ictihâdıma göre sahîh olmamışdır) demekdir.","s":1015},
  {"t":"Meyl dâireleri","c":"İki kutubdan geçen düzlemlere (Meyl düzlemleri) denir. Bu düzlemlerin semâ küresinde hâsıl etdikleri dâirelere (Meyl dâireleri) denir.","s":177},
  {"t":"Meyl düzlemleri","c":"İki kutubdan geçen düzlemlere (Meyl düzlemleri) denir.","s":177},
  {"t":"Mezheb","c":"Bir müctehidin çıkardığı ahkâmın hepsine (Mezheb) denir.","s":49},
  {"t":"Mezhebsiz","c":"Bid’at sâhiblerine ve mülhidlere ve bunların yolunda olan câhil taklîdcilere (Mezhebsiz) denir.","s":473},
  {"t":"Mikyâs","c":"Dâirenin ortasına, dâire kutrunun [çapının] yarısı kadar uzun, düz bir çubuk dikilir. Çubuğun tepesi dâirenin üç muhtelif noktasından aynı uzaklıkda olmalıdır ki, tam dik olsun! Bu dik çubuğa (Mikyâs) denir.","s":182},
  {"t":"Mi’râc","c":"Elliiki yaşında iken, bir gece Mekkeden Kudüse ve oradan göklere götürülüp getirildi. Bu yolculuğuna (Mi’râc) denir.","s":1139},
  {"t":"Miyole lösemi","c":"Bilemediğimiz bir sebeble, kanda lökosit çoğalmasına (Lösemi) kan kanseri denir. Lökosit artması fazla ise, (Miyole lösemi) denir.","s":977},
  {"t":"Mizmâr","c":"Lugat kitâblarında, meselâ (Müncid)de diyor ki, (Ses çıkaran âletlere (Mizmâr) denir).","s":70},
  {"t":"Modérateur","c":"Bunu başarmak için, tabî’î Uranium parçası içine, nötron yakalamıyan çekirdekli atomlardan yapılmış maddeler karışdırılıyor. Bu maddelere (modérateur) deniyor ki, nâzım (tanzîm edici) demekdir.","s":556},
  {"t":"Molekül şebekesi","c":"İki veyâ dahâ ziyâde ametalin mu’ayyen ve az sayıda atomu birleşerek, molekül yapar. Moleküller de, biraraya gelerek, bir cism meydâna getirir. Böyle bir cism, bir sandık şeker külâhına benzer. Bunlara, (Molekül şebekesi) denir.","s":547},
  {"t":"Mu’addilün-nehâr dâiresi=Ekvator","c":"Erdın merkezinden geçen ve mihverine amûd olan sonsuz bir düzleme (Mu’addilün-nehâr=Ekvator düzlemi) denir. Bu ekvator sathının, Erd küresini kesdiği dâireye (Mu’addilün-nehâr dâiresi=Ekvator) denir.","s":177},
  {"t":"Mu’addilün-nehâr=Ekvator düzlemi","c":"Erdın merkezinden geçen ve mihverine amûd olan sonsuz bir düzleme (Mu’addilün-nehâr=Ekvator düzlemi) denir.","s":177},
  {"t":"Mu’âmelât","c":"(Dürr-ül-muhtâr) beşinci cildde, altın ve gümüş kullanmağı anlatırken diyor ki, insanların birbirleri arasında olan işlere (Mu’âmelât) denir.","s":159},
  {"t":"Mubâh","c":"Yapılması emr olunmayan ve yasak da edilmeyen şeylere (Mubâh) denir.","s":18},
  {"t":"Mu’cize","c":"Peygamberlerden “aleyhimüsselâm”, tam temiz oldukları için âdet-i ilâhiyye dışında ve kudret-i ilâhiyye içinde şeyler meydâna gelir. Buna (Mu’cize) denir.","s":747},
  {"t":"Mudârib","c":"Mudârebe, yer yüzünde yürümek demekdir. Şerîklerden bir kısmı sermâye vermek, bir kısmı da iş yapmak üzere kurulur. İş yapanlara, (Mudârib) denir.","s":867},
  {"t":"Mudmerât","c":"(Kudûrî muhtasarı)nı şerh edenlerdendir. Bu şerhıne (Câmi’ul-mudmerât) veyâ kısaca (Mudmerât) denir.","s":1192},
  {"t":"Muhak","c":"Bu hâlde iken, kamerin bize karşı olan yüzü karanlık oluyor. Ayı göremiyoruz. Bu zemâna (Muhak) denir.","s":360},
  {"t":"Muhaşşî","c":"Hâşiyeyi yazana (Muhaşşî) denir.","s":1208},
  {"t":"Muhayyer olmak","c":"Bâyı’ veyâ müşterînin, alış verişden vaz geçebilmek hakkına, (Muhayyer olmak) denir.","s":806},
  {"t":"Muhdis","c":"Abdesti olmıyana (Muhdis) denir.","s":122},
  {"t":"Muhlas","c":"Devâmlı ihlâs sâhiblerine (Muhlas) denir.","s":1049},
  {"t":"Muhlis","c":"Zahmet çekerek elde edilen, devâmsız ihlâsın sâhiblerine (Muhlis) denir.","s":1049},
  {"t":"Mukallid","c":"Müctehid olmıyan müslimâna, (Mukallid) denir.","s":586},
  {"t":"Mukayyed su","c":"Müsta’mel su ve pis su ve çiçek suyu, üzüm suyu gibi, cinsi, sıfatı da söylenen sular mutlak su değildir. Bunlar ile abdest ve gusl alınmaz. Bunlara (Mukayyed su) denir.","s":160},
  {"t":"Müctehid","c":"Bunu ancak Peygamberimiz “sallallahü aleyhi ve sellem” ve Onun Eshâbının hepsi ve diğer müslimânlardan ictihâd makâmına yükselenler yapabilir ki, bu çok yüksek insanlara, (Müctehid) denir.","s":50},
  {"t":"Müdâhene","c":"Dünyâlık ele geçirmek için dîni vermeğe (Müdâhene) denir.","s":398},
  {"t":"Müdârâ","c":"Gücü yetdiği hâlde, fitne çıkarmamak için nasîhat etmezse, (Müdârâ) denir, câiz olur.","s":398},
  {"t":"Müdelles","c":"Başdan yalnız birinci râvîsi bildirilmiyen hadîse (Müdelles) denir.","s":422},
  {"t":"Müekked sünnet","c":"Farz veyâ vâcib olmayıp, Resûlullahın “sallallahü teâlâ aleyhi ve sellem” kendiliğinden emr etdiği veyâ yapdığı ibâdetlere (Sünnet) denir. Bunları devâmlı yaparak, nâdiren terk etmiş ve terk edenlere birşey dememiş ise, (Sünnet-i hüdâ) veyâ (Müekked sünnet) denir.","s":52},
  {"t":"Müellif","c":"Bir âlim kitâb yazarsa, bu kitâba (te’lîf), yazana (müellif) denir.","s":1208},
  {"t":"Müfsidler","c":"Nemâzı bozan şeylere, (Müfsidleri) denir.","s":231},
  {"t":"Mühâyee","c":"Müşterek bir ayn [mal] bâkî kalmak üzere, bunun menfe’atini taksîm etmeğe (Mühâyee) denir.","s":823},
  {"t":"Mükellef","c":"Îmânı olan ve aklı olan ve bâliğ olan erkek ve kadınlara, (Mükellef) denir.","s":988},
  {"t":"Müleffık","c":"Abdülganî Nablüsî hazretleri “rahmetullahi teâlâ aleyh”, (Hadîka) kitâbının ikiyüzyedinci [207] sahîfesinde buyuruyor ki, Mezheblerin ruhsatlarını, ya’nî kolaylıklarını araşdırarak, işini bunlara uygun olarak yapan kimseye (Müleffık) denir.","s":843},
  {"t":"Mülhid","c":"(Redd-ül-muhtâr), üçüncü cild, ikiyüzdoksanaltıncı ve üçyüzdokuzuncu sahîfelerinde diyor ki, Ma’nâları açık ve kat’î olan âyet-i kerîmelere ve hadîs-i şerîflere, te’vîl etse dahî, yanlış ma’nâ vererek ve ma’nâları açıkca anlaşılmıyanları te’vîl etmeden yanlış ma’nâ vererek dinden çıkana, ya’nî îmânı bozuk olana (Mülhid) denir.","s":463},
  {"t":"Mülk-i habîs","c":"Harâmdan topladığı malları, kendi halâl malı ile, yâhud birbirleri ile karışdırsa, (Mülk-i habîs) denir.","s":611},
  {"t":"Mü’min","c":"Resûlullahın “sallallahü aleyhi ve sellem” söylediklerinin hepsini beğenip kalbin kabûl etmesine, ya’nî inanmasına (Îmân) denir. Böylece inanan insanlara, (Mü’min) denir.","s":17},
  {"t":"Münâfık","c":"Müslimân olmıyan, fekat, müslimân görünen kâfire (Münâfık) denir.","s":1051},
  {"t":"Münker","c":"Abdülkâdir-i Geylânî hazretleri buyuruyor ki: Kur’ân-ı kerîme ve hadîs-i şerîflere ve akla uygun şeylere (Ma’rûf), bunlara uymıyan şeylere (Münker) denir.","s":90},
  {"t":"Mürâhık","c":"Oniki ve dokuz yaşlarını doldurup da, bâlig olmamış çocuğa (Mürâhık) denir.","s":227},
  {"t":"Mürekkeb cism","c":"Birbirine benzemiyen atomların yığınına, bileşik cism veyâ (Mürekkeb cism) denir.","s":547},
  {"t":"Mürekkeb veyâ bileşik cism","c":"İki veyâ dahâ çok eleman, birbirleri ile birleşerek, başka sıfatları taşıyan, yeni bir madde meydâna getirilebilir ki, bu yeni maddeye (Mürekkeb veyâ bileşik cism) denir.","s":971},
  {"t":"Mürşid","c":"İnsanları müslimân ve sâlih yapmak için uğraşan velîye (Mürşid) denir.","s":78},
  {"t":"Mürted","c":"Müslimânlıkdan ayrılıp, kâfir olana (Mürted) denir.","s":1051},
  {"t":"Müselles","c":"Üzüm suyu, tâze iken, ya’nî gaz kabarcıkları çıkmadan, köpürmeden önce, ısıtılıp, üçde ikisi uçar, üçde biri kalırsa (Müselles) denir.","s":625},
  {"t":"Müslimân","c":"Otuzüç farz meşhûrdur. Bunlardan dördü esâs olup, nemâz kılmak, oruc tutmak, zekât vermek ve hac etmekdir. Îmân ile berâber bu dört farz, islâmın şartıdır. Îmân edip de ibâdet edene, ya’nî bu dört farzı yapana (Müslim) veyâ (Müslimân) denir.","s":18},
  {"t":"Müslimân olmak","c":"Allahü teâlânın var olduğuna, bir olduğuna ve Muhammed aleyhisselâmın Onun Peygamberi olduğuna ve Peygamberlerinin en üstünü olduğuna ve bunun her sözünün doğru, fâideli olduğuna inanmağa (Îmân etmek) ve (Müslimân olmak) denir.","s":1043},
  {"t":"Müsta’mel su","c":"Abdestde, guslde kullanılan suya (Müsta’mel su) denir.","s":155},
  {"t":"Müste’min kâfir","c":"İbni Âbidîn “rahmetullahi aleyh”, (Redd-ül-muhtâr) kitâbında, kâfirin emân ile, ya’nî izn verilerek islâm memleketine gelmesini anlatırken diyor ki, başka bir memlekete, onların izni ile giren kâfire (Müste’min kâfir) denir.","s":874},
  {"t":"Müşrik","c":"Bir mahlûka ibâdet etmek, taş, ağaç, güneş, yıldız, inek, insan, heykel, resm gibi bir mahlûkda, (Ülûhiyyet sıfatı) bulunduğuna inanarak, ona itâ’at etmek, yalvarmak demekdir. Böyle inanmağa (Şirk) ve inanan kimseye (Müşrik) denir.","s":452},
  {"t":"Nafaka","c":"(Redd-ül-muhtâr) beşinci cild, ikiyüzonbeşinci sahîfede buyuruyor ki, açlığı giderecek kadar yimek ve avret yerini örtecek ve soğukdan, sıcakdan korunacak kadar giyinmek farzdır. Bunlara, (Nafaka) denir.","s":618},
  {"t":"Nâfile ibâdet","c":"Edâ veyâ kazâ etdikden sonra, kendiliğinden tekrâr yapmağa (Nâfile ibâdet) denir.","s":52},
  {"t":"Nasîhat","c":"Emr-i ma’rûfu ve Nehy-i münkeri el ile yapmak, devlet adamlarına, dil ile yapmak, din adamlarına, kalb ile yapmak da her müslimâna farzdır. El ile yapmağa (İhtisâb) ve (Hisbet) denir. Dil ile yapmağa (Va’z) ve (Nasîhat) denir.","s":885},
  {"t":"Natürel","c":"Maddenin yaratılmasına yarayan sebebler arasında insan gücü bulunmazsa, böyle yaratılan maddeye (Tabî’î cism) veyâ (Natürel) denir.","s":433},
  {"t":"Nebî","c":"Allahü teâlâ, Âdem aleyhisselâmdan beri, her bin senede, bir Peygamber vâsıtası ile, insanlara bir din göndermişdir. Bu Peygamberlere “salevâtullahi teâlâ aleyhim ecma’în” (Resûl) denir. Her asrda, en temiz bir insanı Peygamber yaparak, bunlar ile dinleri kuvvetlendirmişdir. Resûllere tâbi’ olan bu Peygamberlere de, (Nebî) denir.","s":18},
  {"t":"Nebîz","c":"Kuru üzüm veyâ hurma, şekeri suya çıkıncaya kadar, soğuk suda bırakılır. Sonra hepsi, kaynayıncaya kadar ısıtılır. Soğuyunca süzülür. Bu sıvıya, (Nebîz) denir.","s":625},
  {"t":"Necâşî","c":"NECÂŞÎ “rahmetullahi teâlâ aleyh”: Habeş pâdişâhlarının hepsine (Necâşî) denir.","s":1154},
  {"t":"Necdî","c":"Bugün, bütün dünyâdaki müslimânlar, üç fırkadır. Birinci fırka, Eshâb-ı kirâmın yolunda olan, hakîkî müslimânlardır. Bunlara (Ehl-i sünnet) ve (Sünnî) ve (Fırka-i nâciyye) Cehennemden kurtulan fırka denir. İkinci fırka, Eshâb-ı kirâma düşman olanlardır. Bunlara (Şî’î) ve (Fırka-i dâlle) sapık fırka denir. Üçüncüsü, sünnîlere ve şî’îlere düşman olanlardır. Bunlara (Vehhâbî) ve (Necdî) denir.","s":401},
  {"t":"Nefs-i nâtıka","c":"İnsanın hakîkati, ya’nî zâtı, kendisi, onun nefsidir. Buna, (Nefs-i nâtıka) denir.","s":754},
  {"t":"Nısf-ün-nehâr dâiresi = Meridiyen","c":"Nısf-ün-nehâr düzleminin, semâ küresini kesdiği dâireye, o mahallin (Nısf-ün-nehâr dâiresi = Meridiyen) denir.","s":177},
  {"t":"Nısf-ün-nehâr hattı","c":"Üfk-ı hakîkî sathını kesdiği doğruya, o mahallin (Nısf-ün-nehâr hattı) denir.","s":177},
  {"t":"Ni’met","c":"İnsânların, sıhhatli, sağlam ve râhat, neş’eli yaşamalarına ve âhıretde sonsuz se’âdete kavuşmalarına sebeb olan fâideli şeylere (Ni’met) denir.","s":1048},
  {"t":"Nokta-i cevvâle","c":"Taş, demir gibi küçük birşeyi, bir ipe bağlayıp [parmağımızda zinciri döndürür gibi] elimizin etrâfında çevirelim. Bir dâire üzerinde dönen bu küçük cisme (Nokta-i cevvâle) denir.","s":930},
  {"t":"Nukûd","c":"(Nakd), külçe veyâ meskûk, ya’nî basılmış para hâlindeki altın ve gümüşlere (Nakd), (Nakdeyn) ve (Nukûd) denir.","s":793},
  {"t":"Nükleon","c":"Proton ile nötronların ikisine de, (Nükleon) denir.","s":560},
  {"t":"Nükleon kuvvetleri","c":"Çekirdeklerde sıkışmış olan protonlar hep müsbet (pozitif) elektrikli olduğundan, birbirlerini itip, çekirdeğin dağılması lâzım iken, çekirdeklerin dağılmamasına sebeb, protonlar arasındaki mu’azzam bir câzibe kuvvetidir. Buna (Nükleon kuvvetleri) denir.","s":560},
  {"t":"Nüsük","c":"Menâsikden herbirine (Nüsük) denir.","s":339},
  {"t":"Olay","c":"Cismlerde meydâna gelen değişikliğe (Hâdise) veyâ (Olay) denir.","s":1041},
  {"t":"Orta Avrupa zemânı","c":"Şarkda yedibuçuk derecedeki tûl dâiresi ile yirmi iki buçuk dereceden geçen tûl dâiresi arasında kullanılan müşterek vasatî sâat, Londra sâatinden bir sâat ileridir. Buna (Orta Avrupa zemânı) denir.","s":190},
  {"t":"Ölüm hastası","c":"(Redd-ül-muhtâr) dördüncü cildde buyuruyor ki, İhtiyâclarını te’mîn etmek için sokağa çıkamıyan hastaya, (Ölüm hastası) denir.","s":816},
  {"t":"Pil","c":"İçerisinde, uygun bir şeklde yerleşdirilmiş, nâzım madde ile uranium bulunan âlete (Pil) denir.","s":556},
  {"t":"Plasma","c":"Kan suyuna (Plasma) denir.","s":977},
  {"t":"Poliçe","c":"Borcu, belli bir zemân sonra, kendine veyâ adı yazılı başka bir kimseye ödemesi için, alacaklının, borcluya gönderdiği mektûba, (Poliçe) denir.","s":833},
  {"t":"Proton","c":"Hidrogen atomunun çekirdeği, artık bölünemiyen mini mini bir dânecikdir. Bu hidrogen çekirdeğine, (Proton) denir.","s":560},
  {"t":"Put","c":"Bir mahlûka ibâdet etmek, taş, ağaç, güneş, yıldız, inek, insan, heykel, resm gibi bir mahlûkda, (Ülûhiyyet sıfatı) bulunduğuna inanarak, ona itâ’at etmek, yalvarmak demekdir. Böyle inanmağa (Şirk) ve inanan kimseye (Müşrik) denir. Bu şeylere (Şerîk), (Ma’bûd), (Put) denir.","s":452},
  {"t":"Putperest","c":"Kendisinde ülûhiyyet sıfatı bulunduğuna inandıkları bir insanın heykeli, mezârı karşısında secde ederek, onun herşeyi yapacağına inananlara (Müşrik) veyâ (Putperest) denir.","s":1043},
  {"t":"Râbıta","c":"Görmek göz ile olduğu gibi, Velînin şeklini, sûretini, kalbine, hayâline getirmekle de, görmüş gibi olup, Allahü teâlâyı hâtırlamağa sebeb olur. Böyle, kalb ile görmeğe (Râbıta) denir ki, kalbi, Allahü teâlâdan başka şeyleri sevmekden, onları düşünmekden kurtaran vâsıtadır.","s":904},
  {"t":"Râsıd","c":"Semâya bakan insana (Râsıd) denir.","s":175},
  {"t":"Ravda-i mutahhera","c":"Medîne câmi’i içinde, Resûlullahın “sallallahü aleyhi ve sellem” kabr-i şerîfi ile câmi’in o zemânki minberi arasındaki, yirmialtı metre uzunluğundaki yere (Ravda-i mutahhera) denir.","s":267},
  {"t":"Ravd-ül-enf","c":"(Sîret-i Resûl) târîhini çok kimseler şerh etmişdir. Bunlar arasında (Aynî) ve (Süheylî) meşhûrdur. Süheylî şerhine (Ravd-ül-enf) denir.","s":1114},
  {"t":"Reaksiyon, tepkime","c":"Maddelerin birbirine te’sîr etmesine (Reaksiyon, tepkime) denir.","s":971},
  {"t":"Reddiyye mes’eleleri","c":"İKİNCİ KISM: Yalnız eshâb-ı ferâiz vardır. Asabe yokdur. Asabe bulunmadığı için eshâb-ı ferâizden geri kalan mal, yine eshâb-ı ferâize, hisseleri oranında bölünür. Ya’nî eshâb-ı ferâize geri verilir, red olunur. Fekat, zevc ile zevceye geri verilmez. Bu ikisine, (Red olunmıyanlar) denir. Zevc ve zevceden başka eshâb-ı ferâize, (Red olunanlar) ya’nî tekrâr verilenler denir. İkinci kısm problemlere, (Reddiyye mes’eleleri) denir.","s":1031},
  {"t":"Red olunmıyanlar","c":"Asabe bulunmadığı için eshâb-ı ferâizden geri kalan mal, yine eshâb-ı ferâize, hisseleri oranında bölünür. Ya’nî eshâb-ı ferâize geri verilir, red olunur. Fekat, zevc ile zevceye geri verilmez. Bu ikisine, (Red olunmıyanlar) denir.","s":1031},
  {"t":"Regâib gecesi","c":"Receb ayının ilk Cum’a gecesine (Regâib gecesi) denir.","s":355},
  {"t":"Resûl","c":"Allahü teâlâ, Âdem aleyhisselâmdan beri, her bin senede, bir Peygamber vâsıtası ile, insanlara bir din göndermişdir. Bu Peygamberlere “salevâtullahi teâlâ aleyhim ecma’în” (Resûl) denir.","s":18},
  {"t":"Revâkıyyûn","c":"ZENON: Eski yunan felesofudur. Bunun felsefesine (Revâkıyyûn) denir.","s":1195},
  {"t":"Rıdâ’","c":"(Nikâye) kitâbının fârisî şerhinde buyuruyor ki, memeden süt emmeğe, (Rıdâ’) denir.","s":586},
  {"t":"Rükn","c":"Her şeyin vücûdü, ya’nî var olması, bir işin yapılmasına bağlıdır. Bu bağlılık, beş dürlü olur: İş, bu şeyin mâhiyyetinin içinde ise, onun bir parçası ise, bu işe, (Rükn) denir.","s":122},
  {"t":"Rükn-i hacer-il esved","c":"Kâ’benin dört köşesine, dört rükn denir. Şâma karşı olana (Rükn-i şâmî), Bağdâda karşı olana (Rükn-i ırâkî), Yemen cihetinde olana (Rükn-i yemânî), dördüncü köşeye de (Rükn-i hacer-il esved) denir.","s":348},
  {"t":"Sâbikûn","c":"Allahü teâlâ, bütün insanlara, îmân etmelerini emr etdi. İnsanlar arasından dilediklerine merhamet edip, bunların akla uyarak îmân etmelerini nasîb eyledi. Bu kullarının kalblerini îmân ile doldurdu. (Yûnüs) sûresinin yirmibeşinci âyetinde meâlen, (Allahü teâlâ kullarını, selâmet, se’âdet yeri olan Cennetine da’vet ediyor. Dilediğini bu yola kavuşdurur) buyuruldu. Akl-ı selîm sâhibi olan, bu mes’ûd insanlara (Sâbikûn) denir.","s":530},
  {"t":"Sâdık","c":"Allahü teâlânın sevgisine kavuşmak için çalışana (Sâlih) denir. Bu sevgiye kavuşmuş olana (Ârif) veyâ (Velî) denir. Başkalarının da kavuşmalarına vâsıta olana (Vesîle) ve (Mürşid), bunların üçüne de (Sâdık) denir.","s":1051},
  {"t":"Sâf cism","c":"Bir maddeden yapılmış cismlere, (Sâf cism) denir.","s":971},
  {"t":"Saf madde","c":"Maddeler, birbirleri ile, her mikdârda karışabilir. Yalnız bir maddeye (Saf madde) denir.","s":546},
  {"t":"Sahâbî","c":"Resûlullahın “sallallahü aleyhi ve sellem” o güzel nûrlu yüzünü gören kimseye, (Sahâbî) denir.","s":1046},
  {"t":"Sâhib","c":"(Vekâlet), bir kimsenin, bir işi yapmak için, başkasını kendi yerine koyması [başkasına iş havâlesi] demekdir. Yerine geçirilen başka kimseye (Vekîl) denir. Vekîl edene (Sâhib) denir.","s":834},
  {"t":"Sahîhayn","c":"(Sahîh-i Müslim) kitâbı, (Buhârî)den sonra, müslimânların en kıymetli temel kitâbıdır. İçinde yedibinikiyüzyetmişbeş [7275] hadîs vardır. Bu iki kitâba (Sahîhayn) denir.","s":1153},
  {"t":"Sahîh temizlik","c":"Âdet zemânından sonra başlıyan onbeş veyâ dahâ ziyâde gün içinde hiç kan görülmezse ve öncesi ve sonrası hayz günleri olursa, bu temiz günlere (Sahîh temizlik) denir.","s":136},
  {"t":"Sâ’î","c":"İbni Âbidîn “rahmetullahi aleyh” buyuruyor ki: Dört nev’ zekât malından ikisine, ya’nî zekât hayvanları ile toprakdan elde edilen mallara (Emvâl-i zâhire) denir. Bunların zekâtlarını, halîfenin me’mûrları gelip toplar. Bu me’mûrlara (Sâ’î) denir.","s":309},
  {"t":"Sâlih","c":"Allahü teâlânın sevgisine kavuşmak için çalışana (Sâlih) denir.","s":1051},
  {"t":"Sâlik","c":"İslâmiyyetin sûretini elde eden, ya’nî vilâyet-i âmmeye, Allahü teâlânın sevgisine kavuşanlar, tarîkatda, ya’nî tesavvuf yolunda ilerliyerek, vilâyet-i hâssaya kavuşabilirler. Bu yolda ilerliyen müslimâna (Sâlik) denir.","s":949},
  {"t":"Sanem","c":"Tahtâvî, (İmdâd) şerhinde diyor ki, Odundan, altından, gümüşden yapılmış insan heykeline, (Sanem) denir.","s":628},
  {"t":"Sapma açısı","c":"Bir şehrde pusula doğrultusu ile hakîkî kutub doğrultusu arasındaki zâviyeye (Sapma açısı) denir.","s":171},
  {"t":"Sathî üfuk","c":"Râsıdın ayaklarından geçen üfk-ı hissî düzlemine (Sathî üfuk) denir.","s":175},
  {"t":"Sathî üfuk hattı","c":"Râsıdın gözünden çıkan şu’â istikâmetine, ya’nî MS doğrusuna (Sathî üfuk hattı) denir.","s":180},
  {"t":"Savme’a","c":"Hıristiyanların ma’bedine (Kilise) ve (Bî’a) veyâ (Savme’a) denir.","s":244},
  {"t":"Sebeb","c":"Her şeyin vücûdü, ya’nî var olması, bir işin yapılmasına bağlıdır. Bu bağlılık, beş dürlü olur: İş, bu şeyin mâhiyyetinin içinde ise, onun bir parçası ise, bu işe, (Rükn) denir. Dışında ise, bu şeye te’sîr ediyorsa, (İllet) denir. Nikâh, evlenmenin illetidir. Te’sîr etmiyorsa, işin yapılması, bu şeyin vücûdünü îcâb ediyorsa, (Sebeb) denir.","s":122},
  {"t":"Segonder anemi","c":"Başka sebebden meydâna geldiği için buna (segonder=bilvâsıta, ikinci anemi) denir.","s":977},
  {"t":"Sekalân","c":"Errahmân sûresinin otuzbirinci âyetinde (Sekalân) buyuruyor ki, (Ey insanlar ve cinnîler!) demekdir.","s":736},
  {"t":"Seker","c":"Hurmanın nakî’i, ya’nî maserasyonu, ya’nî su içinde ısıtmadan bırakılınca, köpüklenir ve tadı keskin olursa (Seker) denir, damlası harâmdır.","s":624},
  {"t":"Selâmün aleyküm","c":"(Selâmün aleyküm) demek, (Ben müslimânım. Benden sana zarar gelmez. Selâmetdesin) demekdir.","s":364},
  {"t":"Selef-i sâlihîn","c":"Eshâb-ı kirâm ile Tâbi’în-i ızâma (Selef-i sâlihîn) denir.","s":768},
  {"t":"Selefiyye","c":"Ehl-i sünnet olmayıp, Ehl-i sünnet âlimlerinin (Nass)larda açık bildirilmemiş olan ahkâmdaki ictihâdlarını beğenmeyen ve bu ma’nâsı açıkca anlaşılamıyan nassları yanlış te’vîl ederek, anladıklarını Selef-i sâlihînin yolu olarak savunan sapıklara (Silfiyye) veyâ (Selefiyye) denir.","s":408},
  {"t":"Semâ kutbu","c":"Erd mihverinin [ekseninin] semâ küresini kesdiği iki noktaya (Semâ kutbu) denir.","s":177},
  {"t":"Semâ küresi","c":"Güneşin ve yıldızların üzerinde hareket etdikleri zan olunan küreye (Semâ küresi) denir.","s":175},
  {"t":"Semt düzlemleri","c":"Bir mahallin şâkûlünden geçen düzlemlere (Semt düzlemleri) denir.","s":177},
  {"t":"Seretân","c":"Yengeç denilen hayvana ve kanser denilen tehlükeli şişlere arabîde (Seretân) denir.","s":626},
  {"t":"Serum","c":"Pıhtı üstündeki berrâk sıvıya (Serum) denir.","s":977},
  {"t":"Sevâb","c":"Va’d etdiği iyiliklerin ölçü birimine, (Ecr) ve (Sevâb) denir.","s":681},
  {"t":"Seyyid","c":"İmâm-ı Hasen evlâdına (Şerîf), imâm-ı Hüseyn evlâdlarına (Seyyid) denir.","s":377},
  {"t":"Sıfât-ı hakîkiyye","c":"Bunlar, hayât [diri olmak], ilm [bilmek], sem’ [işitmek], basar [görmek], kudret [gücü yetmek], irâde [istemek], kelâm [söylemek] ve tekvîn [yaratmak]dır. Bu sekiz sıfata, (Sıfât-ı sübûtiyye) ve (Sıfât-ı hakîkiyye) denir.","s":103},
  {"t":"Silis-ül-bevl","c":"(Kitâbürrahme)de diyor ki, Devâmlı idrâr kaçırmağa (silis-ül-bevl) denir.","s":128},
  {"t":"Sitâre","c":"O sene Mısrdan gönderilen, üzerinde kırmızı ipekle Yasîn sûresi yazılı beyâz ipek perde, Şebeke etrâfına asıldı. Bu perdeye (Sitâre) denir.","s":350},
  {"t":"Spektroskopi","c":"Bir şuâ’lanmada meydâna gelen dalgaların boylarını aramağa, (Spektroskopi) denir.","s":548},
  {"t":"Sun’î ilkâh","c":"(El-halâl vel-harâm)da diyor ki, Erkeğin menîsini, bir tüp veyâ başka şey içinde, nikâhlı zevcesi olmıyan yabancı bir kadının rahmine koyup, çocuk hâsıl olmasına, (Sun’î ilkâh) denir.","s":605},
  {"t":"Sübhâne rabbinâ","c":"Hâlbuki, (Sübhâne rabbinâ) demek, (Biz günâhı çok, âsî kulların yaratanı, yetişdireni her aybdan münezzehdir) demekdir.","s":394},
  {"t":"Sünnet","c":"Allahü teâlânın, açıkca bildirmeyip, yalnız Peygamberimizin “sallallahü aleyhi ve sellem” yapılmasını övdüğü, yâhud devâm üzere yapdığı, yâhud yapılırken görüp de mâni’ olmadığı şeylere (Sünnet) denir.","s":18},
  {"t":"Sünnet-i gayr-ı müekkede","c":"Farz veyâ vâcib olmayıp, Resûlullahın “sallallahü teâlâ aleyhi ve sellem” kendiliğinden emr etdiği veyâ yapdığı ibâdetlere (Sünnet) denir. Bunları devâmlı yaparak, nâdiren terk etmiş ve terk edenlere birşey dememiş ise, (Sünnet-i hüdâ) veyâ (Müekked sünnet) denir. Bunlar, islâm dîninin şi’ârıdır. [Ya’nî, bu dîne mahsûsdurlar. Başka dinlerde yokdurlar.] Vâcibleri terk edeni görünce, terk etmesine mâni’ olurdu. Kendisi ara sıra terk etmiş ise, (Sünnet-i gayr-ı müekkede) denir.","s":52},
  {"t":"Sünnet-i zevâid","c":"Resûlullahın “sallallahü aleyhi ve sellem” ibâdet olarak değil de, âdet olarak, devâmlı yapdığı şeylere (Sünnet-i zevâid) denir.","s":52},
  {"t":"Sünnî","c":"Dört mezhebden birinin îmân ve fıkh bilgilerine tâbi’ olan [uyan] bir müslimâna (Ehl-i sünnet) veyâ (Sünnî) denir.","s":445},
  {"t":"Şâhid","c":"(Tercemet-ül-muhtasar) adındaki (Nikâye)nin fârisî şerhınde diyor ki: Birinin başkasında bulunan hakkını haber verene (Şâhid) denir.","s":884},
  {"t":"Şâkûlü","c":"Râsıdın ayaklarından geçen Erdın yarı çapı istikâmetine râsıdın (Şâkûlü) denir.","s":175},
  {"t":"Şart","c":"Her şeyin vücûdü, ya’nî var olması, bir işin yapılmasına bağlıdır. Bu bağlılık, beş dürlü olur: İş, bu şeyin mâhiyyetinin içinde ise, onun bir parçası ise, bu işe, (Rükn) denir. Dışında ise, bu şeye te’sîr ediyorsa, (İllet) denir. Nikâh, evlenmenin illetidir. Te’sîr etmiyorsa, işin yapılması, bu şeyin vücûdünü îcâb ediyorsa, (Sebeb) denir. Vakt, nemâzın sebebidir. Îcâb etmiyorsa, işin yapılmaması ile, o şey de yok olursa, (Şart) denir.","s":122},
  {"t":"Şebeke-i se’âdet","c":"Beşyüzelli senesinde, Cemâleddîn-i İsfehânî, ikinci dıvar etrâfına sandal ağacından parmaklık yapdı. Bu parmaklığa (Şebeke-i se’âdet) denir.","s":350},
  {"t":"Şefî’","c":"Başkasına satılmış olan bir mülkü, satış değeri ile satınalmak hakkına (Şüf’a) denir. Bu hakka mâlik olan kimseye, (Şefî’) denir.","s":536},
  {"t":"Şehvet","c":"Allahü teâlâ, insanların ve hayvanların, yaşayabilmeleri ve üremeleri için, onlarda iki kuvvet yaratdı. Biri, muhtâc oldukları, lezzet aldıkları şeyleri istemek, onlara kavuşmak kuvvetidir. Bu kuvvete, (Şehvet) denir.","s":529},
  {"t":"Şer","c":"Dünyâda yapılan her işden ve düşünceden, dünyâda ve âhıretde fâide veyâ zarar hâsıl olur. Fâide hâsıl olanlara (Hayr), zarar hâsıl olanlara (Şer) denir.","s":697},
  {"t":"Şerî’atde tevhîd, tevhîdde şerî’at","c":"Süâl — İnsanın elinde birşey yoksa, niçin sevâb ve azâb oluyor ve niçin dinler, şerî’atler gönderiliyor? Cevâb — Bu süâle (Şerî’atde tevhîd) ve (Tevhîdde şerî’at) denir ki, burada çok kimseler boğulmuşdur.","s":680},
  {"t":"Şerîf","c":"İmâm-ı Hasen evlâdına (Şerîf), imâm-ı Hüseyn evlâdlarına (Seyyid) denir.","s":377},
  {"t":"Şerîf-i Ca’ferî","c":"Zeyneb, Abdüllah bin Ca’fer Tayyâr ile nikâhlanıp, Alî ve Ümm-i Gülsüm ve zürriyyetleri oldu. Bunlara (Şerîf-i Ca’ferî) denir.","s":1100},
  {"t":"Şer’î gurûb","c":"Üçüncü gurûb, arka kenârın, şer’î üfka nazaran irtifâ’ının sıfır olduğu hesâb olunan vaktdir. Buna (Şer’î gurûb) denir.","s":186},
  {"t":"Şer’î irtifâ’","c":"Güneşin kenârının, şer’î üfka göre olan irtifâ’ına (Şer’î irtifâ’) denir.","s":181},
  {"t":"Şer’î üfk hattı","c":"Râsıdın bulunduğu yerin en yüksek noktasının zâhirî üfk hattından geçen P (Şer’î üfk) düzlemidir ki, bu düzlemin yer küresini kesdiği q dâireye (şer’î üfk hattı) denir.","s":175},
  {"t":"Şer’î zevâl mahalli","c":"Râsıd, bulunduğu mahallin en yüksek yerine çıkınca, semâdaki (zevâl mahalli dâiresi), en dışarda ve en büyük olur. Bu en büyük zevâl mahalli dâiresine Râsıdın (Şer’î zevâl mahalli) denir.","s":181},
  {"t":"Şeyh-ul-hadîs","c":"İkiyüzbin hadîs-i şerîfi ezbere bilene (Şeyh-ul-hadîs) denir.","s":423},
  {"t":"Şî’î","c":"(Hadîka)da, ikinci kısmın sonunda buyuruyor ki, Hazret-i Alîyi üç halîfeden üstün tutana (Şî’î) denir.","s":408},
  {"t":"Şirk","c":"Hıristiyanların ikinci kısmı, Îsâda ülûhiyyet sıfatları vardır. Babası gibi, her dilediğini yaratır. Ebedî, ezelî olarak diridir diyorlar. Böyle inanarak yalvarmağa, ibâdet etmek, tapınmak denir. Böyle inanmağa (Şirk) denir.","s":570},
  {"t":"Şüf’a","c":"Başkasına satılmış olan bir mülkü, satış değeri ile satınalmak hakkına (Şüf’a) denir.","s":536},
  {"t":"Tabî’at","c":"Maddelerin, cismlerin ve maddelerde bulunan enerjilerin hepsine (Âlem) veyâ (Tabî’at) denir.","s":1041},
  {"t":"Tâbi’în","c":"Resûlullahın “sallallahü aleyhi ve sellem” o güzel nûrlu yüzünü gören kimseye, (Sahâbî) denir. Birkaç dânesine (Eshâb) denir. O güzeli göremeyip de, yalnız, Sahâbîyi görenlere (Tâbi’în) denir.","s":1046},
  {"t":"Ta’dîl-i zemân","c":"Hakîkî ve vasatî gün uzunlukları aynı iken, sonraki günlerde hâsıl olan farklara (Ta’dîl-i zemân) denir.","s":189},
  {"t":"Tahkîm","c":"İki kimsenin, aralarında uyuşamadıkları kul hakkı için, bir veyâ birkaç müslimânı hâkim ta’yîn etmeleri câizdir. Buna, (Tahkîm) denir.","s":884},
  {"t":"Tahrîmen mekrûh","c":"Nemâzın mekrûhları iki dürlüdür: Yalnız mekrûh denildiği zemân (Tahrîmen mekrûh) demekdir ki, delîlinden zan ile anlaşılan yasaklardır.","s":236},
  {"t":"Takdîr","c":"(Dürr-i yektâ) şerhinin sâhibi “rahmetullahi teâlâ aleyh” diyor ki, İnsanların kalbleri ile veyâ bedenleri ile yapdıkları her işin ve canlılarda ve cansız şeylerde meydâna gelen her işin, Allahü teâlânın ezelde bilmesi ve dilemesi ve halk etmesi ile olmalarına (Kader) ve (Takdîr) denir.","s":702},
  {"t":"Takvîm-i Celâlî","c":"Celâlüddîn, Selçûkî pâdişâhlarından üçüncüsüdür. Alb Arslanın oğludur. 447 [m. 1054] de tevellüd, 485 [m. 1091] de Bağdâdda zehr verilerek vefât etdi. İsfehânda defn edildi. Babası şehîd olunca, vezîr Nizâm ül mülkün yardımı ile 465 [m. 1072] de sultân oldu. Mâverâünnehri, Şâmı, Mısrı, Anadolunun çoğunu aldı. Abbâsî halîfesini emrine aldı. Çok hayrât yapdı. [471] hicrî senesinde, güneş takvîmi yapdırdı. Buna (Takvîm-i Celâlî) denir.","s":1134},
  {"t":"Talâk-ı bâin","c":"Boşanmak için konulmuş olan kelimeleri erkeğin zevcesine karşı söylemesi ile talâk hâsıl olur. Bu kelimelerden birini söyler söylemez hâsıl olan ayırmağa (Talâk-ı bâin) denir.","s":580},
  {"t":"Talâk-ı ric’î","c":"İddet zemânı geçdikden sonra hâsıl olan talâka, (Talâk-ı ric’î) denir.","s":580},
  {"t":"Tam râbıta","c":"Kendisini, Velînin şeklinde, kıyâfetinde görmek, ya’nî böyle râbıta yapmakdır. Kur’ân-ı kerîm okurken ve dinlerken, ders, va’z dinlerken, nemâz kılarken, her ibâdeti yaparken, kendini o kıyâfetde düşünür. Bunları yapan, kendi değil, odur der. Böyle yapılan ibâdetlerden çok lezzet duyulurdu. Râbıta yapmakla çabuk ilerlerdi. Allahü teâlânın rızâsına kavuşurdu. Üçüncü kısma (Tam râbıta) denirdi.","s":922},
  {"t":"Tâm şehîd","c":"Cünüb, hâiz olmıyan, âkıl ve bâlig bir müslimân, zulm ile, haksız olarak, vurucu veyâ kesici vâsıtalarla öldürülünce ve harbde din düşmanları ile, Allah için cihâd ederken, düşman tarafından, sulhda âsîler, yol kesiciler, şehr eşkıyâları, gece hırsız tarafından, herhangi bir vâsıta ile öldürülünce, hemen ölürlerse veyâ müslimânların ve ehl-i zimmetin cânlarını, mallarını korumak için olan çarpışma yerinde bulunan ölü üzerinde yara, kan akması gibi öldürülme alâmetleri görülürse veyâ şehrde öldürülmüş bulunup, kâtili bilinir ve kısâs yapılması lâzım gelirse, bunlara (Dünyâ ve âhıret şehîdi) ve (Tâm şehîd) denir.","s":998},
  {"t":"Tam temizlik","c":"Sahîh temizliğe ve hükmî temizliğe (Tam temizlik) denir.","s":136},
  {"t":"Tasvîr","c":"Kumaşa, dıvâra ve başka yerlere yapılmış cânlı ve cânsız resmlerine, (Sûret) veyâ (Tasvîr) denir.","s":628},
  {"t":"Ta’vîz","c":"Âyet-i kerîme ile ve Resûlullahdan gelen düâlar ile Rukye yapmağa, (Ta’vîz) denir.","s":783},
  {"t":"Tayf analizi=spektral analiz","c":"Herhangi bir madde tarafından yayılan şuâ’lanmanın spektroskopisini yaparak, bu maddede hangi elementlerin bulunduğunu aramağa (Tayf analizi=spektral analiz) denir.","s":548},
  {"t":"Tebe’ı tâbi’în","c":"Tâbi’înden sonra, insanların en üstünleri, Tâbi’îni gören ve onların sohbetinde yetişen müslimânlardır. Bunlara (Tebe’ı tâbi’în) denir.","s":495},
  {"t":"Tebzîr","c":"Malı, islâmiyyetin ve mürüvvetin uygun görmediği yerlere dağıtmağa (İsrâf) veyâ (Tebzîr) denir.","s":640},
  {"t":"Tefekkür","c":"Ağızla söylemeyip, yalnız kalb ile yapılan zikrdir. Zikrin nasıl yapılacağı (Mektûbât-ı Ma’sûmiyye) c.2, 113. mektûbda yazılıdır. Buna, tesavvufda (Zikr-i hafî) denir. Bu da, yalnız Zât-ı ilâhiyyeyi zikrdir. Yâhud, sıfatlarını düşünerek yapılır. Ni’metleri de düşünülürse, buna (Tefekkür) denir.","s":903},
  {"t":"Tefsîr","c":"Resûlullahın “sallallahü aleyhi ve sellem” bildirdiği ma’nâlara (Tefsîr) denir.","s":9},
  {"t":"Telfîk","c":"Dört mezhebin kolay taraflarını araşdırıp, birbirine karışdırmağa (Telfîk) denir.","s":470},
  {"t":"Telfîk-ı mezâhib","c":"Dört mezhebin kolaylıklarını araşdırıp, bunları bir araya toplayarak, yeni bir kolaylıklar mezhebi uydurmağa (Telfîk-ı mezâhib) denir.","s":468},
  {"t":"Temîme","c":"Ma’nâsı bilinmiyen veyâ küfre sebeb olan rukyeyi okumağa, (Efsûn) denir. Bunu veyâ nazarlık denilen şeyleri kendi üzerinde taşımağa, (Temîme) denir.","s":784},
  {"t":"Temkin","c":"Güneşin merkezinin hakîkî üfukdan gurûbundan sonra, arka kenârının, bu gurûb vaktinden, bu irtifâ’ zâviyesi kadar, dahâ aşağıya, ya’nî üfk-ı şer’îye inerek, ziyânın en yüksek tepeden gayb olması için geçen zemâna (Temkin) denir.","s":186},
  {"t":"Tenvîr dâiresi","c":"Hasîb beğ, (Kozmografya) kitâbında diyor ki: Güneşden, birbirine müvâzî [paralel] olarak gelen şuâ’lardan, Erd küresine temâs ederek geçenlerin, bu temâs noktaları, büyük bir dâire hâsıl eder. Bu dâireye (Tenvîr dâiresi) denir.","s":183},
  {"t":"Tenzîhen mekrûh","c":"Yasak olmasına bir delîl, sened bulunmayıp, yapılmaması iyi olan şeye (Tenzîhen mekrûh) denir.","s":236},
  {"t":"Tesavvuf","c":"İkincisi, (Ulûm-i bâtınıyye), kalb bilgileridir. Bunlar, Resûlullahın mubârek kalbinden çıkıp, Evliyânın kalblerine gelen bilgilerdir. Bu bilgilere (Tesavvuf) denir.","s":1043},
  {"t":"Teselsül","c":"Allahü teâlâ, kadîm olmasaydı, hâdis olsaydı, onu yaratan bir yaratıcı bulunurdu. Bu yaratıcı kadîm ise, Allah odur. Hâdis ise, onu da yaratan biri lâzım olur. Böylece, kadîm olmıyan yaratıcılar zinciri mevcûd olur. Bu zincire, (Teselsül) denir.","s":760},
  {"t":"Tevâcüd","c":"İrâdî ve ihtiyârî olarak raks etmeğe, (Tevâcüd) denir.","s":721},
  {"t":"Tevbe bî’ati","c":"(BÎ’AT), söz vermek ve bu sözünde durmak demekdir. Tesavvuf yolunda çok kullanılan bir kelimedir. Bunu kullanmak, Eshâb-ı kirâmın sünnetidir “radıyallahü teâlâ anhüm”. Bî’at, üç kısmdır: Birincisi, bir büyüğün önünde, günâh işlememek için söz vermekdir. Buna, (tevbe bî’ati) denir.","s":766},
  {"t":"Tevbe etmek","c":"Kusûrlarını düşünüp, bunları yapdığına mahcûb olmalı, utanmalıdır. Pişmân olup üzülmelidir. Hiç günâh yapmamağa karâr vermelidir. Bu üzülmeğe ve karâra (Tevbe etmek) denir.","s":64},
  {"t":"Te’vîl","c":"Bir kelimenin, Allahü teâlâ ve Resûlullah tarafından, açık bildirilmemiş ma’nâlarından, islâmiyyete uygun olanı seçmeğe (Te’vîl) denir.","s":771},
  {"t":"Tılâ","c":"Tâze şıra, ateşde veyâ güneşde ısıtılıp üçde ikisinden azı uçarsa, [üçde birinden çok kalırsa], bu kalana, (Tılâ) denir.","s":624},
  {"t":"Timsâl","c":"Kumaşa, dıvâra ve başka yerlere yapılmış cânlı ve cânsız resmlerine, (Sûret) veyâ (Tasvîr) denir. Yalnız cânlı resmlerine, (Timsâl) denir.","s":628},
  {"t":"Titreşimli akımın frekansı","c":"Sâniyedeki gidip gelme sayısına (Titreşimli akımın frekansı) denir.","s":986},
  {"t":"Tivele","c":"Muhabbet hâsıl etmek için yapılan rukyelere, (Tivele) denir.","s":784},
  {"t":"Todesstrahlen","c":"Harblerde kullanılabileceklerinden, bunlara ölüm şuâ’ları (Todesstrahlen) denir.","s":974},
  {"t":"Tokmaktepe","c":"Sonra, halîfelerinden Tokmak dede, vakfını ta’yîn etdi. Bu da orada medfûndur. Bunun için oradaki kabristâna (Tokmaktepe) denir.","s":1103},
  {"t":"Tuğra","c":"Osmânlı pâdişâhlarının mührlerine, (Tuğra) denir.","s":621},
  {"t":"Türkistân","c":"Merv şehri buradadır. Bunun cenûbu, Îrânın (Cürcân) ve (Horasan) vilâyetleridir. Buraya şimdi (Türkmenistân) deniyor. Aral gölünün şimâline (Kazakistân) deniyor. Mâ-verâ-ün-nehrin cenûbuna (Özbekistân) deniyor. Buhâra, Semerkand, Taşkend buradadır. Bunun şarkına (Tâcikistân) deniyor. Yârkend, Fergâne ve Kâşgar buradadır. Bu memleketlerin hepsine (Türkistân) denir.","s":431},
  {"t":"Uçuk","c":"UÇUK: Fransızca (perléche) denir. Alt ve üst dudakların birleşdiği yerde çıkan ufak yaradır.","s":674},
  {"t":"Ukûbât","c":"(Dürr-ül-muhtâr) üçüncü cüz’de buyuruyor ki: Döğerek, kolu keserek, recm ederek, ya’nî öldürünceye kadar taş atarak veyâ öldürerek yapılan cezâlara (Ukûbât) denir.","s":879},
  {"t":"Ulûm-i hikemiyye","c":"İslâm bilgilerinin ikinci kısmı (Ulûm-i akliyye)dir. Canlıları öğretene (Ulûm-i tıbbiyye), cansızları öğretene (Ulûm-i hikemiyye) denir.","s":25},
  {"t":"Ulûm-i islâmiyye","c":"Kıymetli mektûbunuzun başında, din âlimlerinin, müslimânların öğrenmesi lâzım olan bilgilere (Ulûm-i islâmiyye) denir, dediklerini yazıyorsunuz.","s":413},
  {"t":"Ulûm-i nakliyye","c":"Böyle varlıkları anlamak, mu’cizelerle, üstünlüğü belli Peygamberlere “aleyhimüssalevâtü vetteslîmât” bildirilmekle ve Peygamberlerden “aleyhimüsselâm” işitmekle olur. Böyle bilgilere, (Ulûm-i nakliyye) denir.","s":543},
  {"t":"Urûz","c":"Hayvândan başka, menkûl olan kıyemî mallara, (Urûz) denir.","s":793},
  {"t":"Uşr","c":"Toprakdan alınan mahsûlün zekâtına (Uşr) denir.","s":303},
  {"t":"Üfk düzlemleri","c":"ME hattı râsıdın şâkûlüdür. Bu şâkûle dik olan düzlemlere râsıdın (Üfk düzlemleri) denir.","s":175},
  {"t":"Üfk-ı zâhirî hattı","c":"Etrâfımıza bakınca yer ile gök, büyük bir dâirenin kavsi üzerinde birleşmiş gibi görünüyor. Bu dâireye (Üfk-ı zâhirî hattı) denir.","s":175},
  {"t":"Ülûhiyyet sıfatları","c":"Allahü teâlâya mahsûs olan sıfatlara, (Sıfât-i zâtiyye)ye ve (Sıfât-i sübûtiyye)ye (Ülûhiyyet sıfatları) denir.","s":452},
  {"t":"Üveysî","c":"Rûhların terbiye etdiği kimseye (Üveysî) denir.","s":1189},
  {"t":"Vâcib","c":"İnanması farz olmayıp, vâcib olan, yapması farz olan emrlere (Vâcib) denir.","s":230},
  {"t":"Vasatî gün","c":"Hakîkî zevâl vaktinde, zemânları ölçen, meselâ kol sâatimiz, 12 de iken başlıyarak, ertesi gün 12 ye kadar geçen tam 24 sâatlik zemâna bir (Vasatî gün) denir.","s":188},
  {"t":"Vatan","c":"İnsanın mukîm olduğu, yerleşdiği yere (Vatan) denir.","s":224},
  {"t":"Vecd","c":"İhtiyârî olmıyan raksa (Vecd) denir.","s":721},
  {"t":"Vehhâbîlik","c":"Sapık din adamı Ahmed ibni Teymiyyenin kitâblarındaki bozuk fikrleri ile ingiliz câsûsu Hempherin yalanlarının ve iftirâlarının karışımına (Vehhâbîlik) denir.","s":482},
  {"t":"Vekîl","c":"(Vekâlet), bir kimsenin, bir işi yapmak için, başkasını kendi yerine koyması [başkasına iş havâlesi] demekdir. Yerine geçirilen başka kimseye (Vekîl) denir.","s":834},
  {"t":"Velî","c":"Allahü teâlânın sevgisine kavuşmak için çalışana (Sâlih) denir. Bu sevgiye kavuşmuş olana (Ârif) veyâ (Velî) denir.","s":1051},
  {"t":"Vera’","c":"İbni Âbidîn, imâmlığın şartlarında buyuruyor ki, Şübhelilerden sakınmağa, ya’nî şübhelilerden ittikâya (Vera’) denir.","s":96},
  {"t":"Vesen","c":"Taşdan yapılan insan heykeline, (Vesen) denir.","s":628},
  {"t":"Vesîle","c":"(İcâzet) ve (Hilâfet), tâliblerin kalblerine ihlâs yerleşdirmesi için, olgun birisine izn vermek demekdir. Kendisine izn verilen zâta (Halîfe) veyâ (Vesîle) denir.","s":768},
  {"t":"Ya’kûbiyye","c":"DİOSKORÜS: İskenderiyye patrîki idi. [m. 451] senesinde Kadıköyünde toplanan beşinci meclisde, fikrleri red edildi. Fikrlerine (Monofisiyye) veyâ (Ya’kûbiyye) denir.","s":1089},
  {"t":"Yıldız günü","c":"Bir yıldızın, bulunulan mahallin Nısf-ün-nehârından iki geçişi arasındaki zemâna bir (Yıldız günü) denir.","s":183},
  {"t":"Yıldız sâati","c":"Bir yıldızın, bulunulan mahallin Nısf-ün-nehârından iki geçişi arasındaki zemâna bir (Yıldız günü) denir. Bu zemânın 24 de birine bir (yıldız sâati) denir.","s":183},
  {"t":"Yobaz","c":"İster Ehl-i sünnet olsun, ister bid’at sâhibi olsun, dînini dünyâ çıkarlarına âlet eden, ya’nî dünyâlığa kavuşmak için dîninden veren câhillere (Yobaz) denir.","s":473},
  {"t":"Zâhirî gurûb","c":"İkinci gurûb, arka kenârın, râsıdın bulunduğu mahallin zâhirî üfuk hattına nazaran zâhirî irtifâ’ının sıfır olduğu, ya’nî bu üst kenârının, mahallin üfk-ı zâhirî hattından gayb olduğunun görüldüğü vaktdir. Buna (Zâhirî gurûb) denir.","s":186},
  {"t":"Zâhirî irtifâ’ kavsi","c":"Güneşin bir Z kenârından geçen semt dâiresinin, bu kenârı kesdiği nokta ile, hissî, mer’î, riyâdî ve hakîkî üfuk düzlemlerini kesdiği, semâdaki iki nokta arasındaki kavslerine, bu üfuklara nazaran (Zâhirî irtifâ’ kavsi) denir.","s":177},
  {"t":"Za’îm","c":"Kirâ almak hakkı bulunan askere (Timarcı), subaylara (Za’îm) denirdi.","s":305},
  {"t":"Zarûret","c":"İnsanı birşey yapmağa zorlıyan semâvî sebebe, ya’nî insanın elinde olmıyarak hâsıl olan sebebe (Zarûret) denir.","s":135},
  {"t":"Zındık","c":"Hiçbir dinde olmayıp da, dinsiz düşüncelerini müslimânlık imiş gibi, fâsid, bozuk delîller ile isbâta kalkışarak, müslimânların îmânlarını bozmak istiyene (Zındık) denir.","s":463},
  {"t":"Zikr-i cehrî","c":"Kalb ile ve dil ile birlikde zikrdir. Dil ile kendi işitecek kadar söylenirse, islâmiyyetde (Zikr-i hafî) denir. Âyet-i kerîmede emr olunan, bu zikr-i hafîdir. Başkası da işitirse (Zikr-i cehrî) denir.","s":903},
  {"t":"Zikr-i hafî","c":"Kalb ile ve dil ile birlikde zikrdir. Dil ile kendi işitecek kadar söylenirse, islâmiyyetde (Zikr-i hafî) denir.","s":903},
  {"t":"Zimmî","c":"Bunlar, islâmın kuvveti ve büyüklüğü karşısında, küçüklüklerini anlamış, cizye vermeği kabûl ederek islâmın hâkimiyyetine ve adâletine sığınmışdır. Bu kâfirlere (Ehl-i zimmet) veyâ (Zimmî) denir.","s":39},
  {"t":"Zühd","c":"Şübheli olmak korkusu ile mubâhların çoğunu terk etmeğe de (Zühd) denir.","s":96},
  {"t":"Züyûf","c":"Altını, gümüşü yarıdan fazla olan nukûddan; altını, gümüşü en çok olanına (Ceyyid), dahâ az olanlarına (Züyûf) denir.","s":793}
];
